import {W163} from './namedays-plain-r163.js';
// Wording pass of 16 November 2026 (round 140): displayed text names no dictionaries, studies or research
// authors and does not present a name as being of Russian origin. Keys are exact English sentences of the
// research text; null drops the sentence in every language, an array [lv, ru, en, lt, et] replaces it at the
// same sentence position. Research modules keep their original wording and provenance.
const D=null;
const A=(lv,ru,en,lt,et)=>[lv,ru,en,lt,et];
const cmp=(n,b)=>A(`${n} varētu salīdzināt ar ${b}.`,`${n} можно сопоставить с ${b}.`,`${n} could be compared with ${b}.`,`${n} galima palyginti su ${b}.`,`${n} võib võrrelda nimega ${b}.`);
const eug=(n,b)=>[`${n} could be compared with the documented dictionary form ${b}.`,cmp(n,b)];
const W=new Map([
 ['That is why the name has long been familiar in Russia and Eastern Europe; the Latvian spelling Tatjana follows the Russian pronunciation.',A('Tāpēc vārds jau sen ir pazīstams Austrumeiropā.','Поэтому имя давно известно в Восточной Европе.','That is why the name has long been familiar in Eastern Europe.','Todėl vardas seniai žinomas Rytų Europoje.','Seetõttu on nimi Ida-Euroopas ammu tuntud.')],
 ['Rodions is the Latvian form of Russian Родион and Ukrainian Родіон.',A('Rodions ir vārda Rodion latviskā forma.','Rodions — латышская форма имени Родион.','Rodions is the Latvian form of the name Rodion.','Rodions – latviška vardo Rodion forma.','Rodions on nime Rodion läti kuju.')],
 ['Trofims is the Latvian form of Russian Трофим, from Greek Trophimos and trophe, “nourishment”; it is explained as “nourisher” or “nourished, brought up”.',A('Trofims cēlies no grieķu Trophimos un trophe — «barība»; to skaidro kā «barotājs» vai «audzināts».','Трофимс восходит к греческому Trophimos и trophe — «пища»; его объясняют как «кормилец» или «вскормленный».','Trofims comes from Greek Trophimos and trophe, “nourishment”; it is explained as “nourisher” or “nourished, brought up”.','Trofims kilęs iš graikų Trophimos ir trophe („maistas“); aiškinamas kaip „maitintojas“ arba „išaugintas“.','Trofims pärineb kreeka nimest Trophimos ja sõnast trophe ‘toit’; seda seletatakse kui ‘toitja’ või ‘üleskasvatatu’.')],
 ['Vasilisa is the official Latvian rendering of Russian Василиса; Vasiļisa, with a palatal ļ, is a different form.',A('Vasilisa ir oficiālā latviskā atveide; Vasiļisa ar mīksto ļ ir cita forma.','Vasilisa — официальная латышская передача имени; Vasiļisa с мягким ļ — другая форма.','Vasilisa is the official Latvian rendering of the name; Vasiļisa, with a palatal ļ, is a different form.','Vasilisa – oficiali latviška vardo forma; Vasiļisa su minkštuoju ļ – kita forma.','Vasilisa on nime ametlik läti kuju; Vasiļisa pehme ļ-ga on teine kuju.')],
 ['Agafija is the Russian form of Agata.',A('Agafija ir vārda Agata forma.','Agafija — форма имени Агата.','Agafija is a form of Agata.','Agafija – vardo Agota forma.','Agafija on nime Agata kuju.')],
 ['The rendering manual documents Dorotija as a Latvian form of English Dorothy and Dorothea.',A('Dorotija ir angļu Dorothy un Dorothea latviskā forma.','Dorotija — латышская форма английских Dorothy и Dorothea.','Dorotija is a Latvian form of English Dorothy and Dorothea.','Dorotija – latviška angliškų Dorothy ir Dorothea forma.','Dorotija on inglise nimede Dorothy ja Dorothea läti kuju.')],
 ['Raja is a Russian pet form of Iraida and Raisa.',A('Raja ir vārdu Iraida un Raisa mīlvārds.','Рая — ласкательная форма имён Ираида и Раиса.','Raja is a pet form of Iraida and Raisa.','Raja – vardų Iraida ir Raisa maloninė forma.','Raja on nimede Iraida ja Raisa hellitusvorm.')],
 ['In Lithuanian, however, Lina is the feminine counterpart of Linas, the Lithuanian form of Linus, and Lithuanian name dictionaries link it directly with the word linas, “flax”.',A('Lietuviešu valodā Lina ir vārda Linas (lietuviskā Linus forma) sieviešu pāris, un to tieši saista ar vārdu linas — «lini».','В литовском Lina — женская пара к Linas (литовская форма Linus), и её прямо связывают со словом linas — «лён».','In Lithuanian, however, Lina is the feminine counterpart of Linas, the Lithuanian form of Linus, and it is linked directly with the word linas, “flax”.','Lietuvių kalboje Lina yra vardo Linas (lietuviškos Linus formos) moteriškoji pora ir tiesiogiai siejama su žodžiu linas.','Leedu keeles on Lina nime Linas (Linuse leedu kuju) naispaariline ja seda seostatakse otse sõnaga linas ‘lina’.')],
 ['Gotfrīds (printed in the dictionary as Gotfrids) is formed from Old High German got, “god”, and fridu, “peace”.',A('Gotfrīds (arī Gotfrids) darināts no senaugšvācu got — «dievs» — un fridu — «miers».','Gotfrīds (также Gotfrids) образовано от древневерхненемецких got — «бог» — и fridu — «мир».','Gotfrīds (also Gotfrids) is formed from Old High German got, “god”, and fridu, “peace”.','Gotfrīds (taip pat Gotfrids) sudarytas iš senosios aukštaičių vokiečių got („dievas“) ir fridu („taika“).','Gotfrīds (ka Gotfrids) on moodustatud vanaülemsaksa sõnadest got ‘jumal’ ja fridu ‘rahu’.')],
 ['Filomena (printed in the dictionary as Filomēna) comes from Greek phileomenos, “beloved”.',A('Filomena (arī Filomēna) cēlies no grieķu phileomenos — «mīlētā».','Filomena (также Filomēna) восходит к греческому phileomenos — «любимая».','Filomena (also Filomēna) comes from Greek phileomenos, “beloved”.','Filomena (taip pat Filomēna) kilusi iš graikų phileomenos („mylima“).','Filomena (ka Filomēna) pärineb kreeka sõnast phileomenos ‘armastatu’.')],
 ['The older root of Amalda is unexplained; the name was missing from the older Latvian name dictionary.',A('Vārda Amalda senākā sakne nav izskaidrota.','Более древний корень имени Amalda не объяснён.','The older root of Amalda is unexplained.','Senesnė vardo Amalda šaknis nepaaiškinta.','Nime Amalda vanem tüvi on seletamata.')],
 ['Ileana (printed in the dictionary as Ileāna) is the Romanian form of Helēna and is also linked with Juliāna.',A('Ileana (arī Ileāna) ir rumāņu Helēnas forma, ko saista arī ar Juliānu.','Ileana (также Ileāna) — румынская форма Helēna; её связывают и с Juliāna.','Ileana (also Ileāna) is the Romanian form of Helēna and is also linked with Juliāna.','Ileana (taip pat Ileāna) – rumuniška Helēnos forma, siejama ir su Juliāna.','Ileana (ka Ileāna) on Helēna rumeenia kuju ja seda seostatakse ka nimega Juliāna.')],
 ['Kazimira (printed in the dictionary as Kazimīra) is the feminine form of Kazimirs.',A('Kazimira (arī Kazimīra) ir vārda Kazimirs sieviešu forma.','Kazimira (также Kazimīra) — женская форма имени Kazimirs.','Kazimira (also Kazimīra) is the feminine form of Kazimirs.','Kazimira (taip pat Kazimīra) – moteriška vardo Kazimirs forma.','Kazimira (ka Kazimīra) on nime Kazimirs naisvorm.')],
 ['Daira and Dairis are linked with the old Latvian adjective dairs, whose modern sense is “strange, unknown, eerie”; dictionaries mark it as dated and also give the sense “shy”.',A('Daira un Dairis saistās ar seno latviešu īpašības vārdu dairs — «svešs, nepazīstams, baigs»; tam ir arī nozīme «kautrs».','Daira и Dairis связаны со старым латышским прилагательным dairs — «странный, незнакомый, жуткий»; есть и значение «робкий».','Daira and Dairis are linked with the old Latvian adjective dairs, “strange, unknown, eerie”, which also meant “shy”.','Daira ir Dairis siejami su senu latvių būdvardžiu dairs („keistas, nepažįstamas, baugus“); jis reiškė ir „drovus“.','Daira ja Dairis on seotud vana läti omadussõnaga dairs ‘võõras, tundmatu, õudne’, millel oli ka tähendus ‘arg’.')],
 ['Lithuanian name dictionaries explain it as a short form of Danielė, going back to the Hebrew “God is my judge”.',A('To skaidro kā Danielės saīsinājumu, kas iet atpakaļ uz ebreju «Dievs ir mans tiesnesis».','Его объясняют как сокращение имени Danielė, восходящего к еврейскому «Бог — мой судья».','It is explained as a short form of Danielė, going back to the Hebrew “God is my judge”.','Jis aiškinamas kaip Danielės trumpinys, kilęs iš hebrajų „Dievas – mano teisėjas“.','Seda seletatakse nime Danielė lühendina, mis läheb tagasi heebrea väljendile ‘Jumal on mu kohtumõistja’.')],
 ['It is included in a 2013 study of rare names in Latvia, based on register data up to 1 January 2012.',A('Tas pieder pie retajiem Latvijas vārdiem.','Оно относится к редким именам Латвии.','It is one of the rare names of Latvia.','Jis priklauso retiems Latvijos vardams.','See kuulub Läti haruldaste nimede hulka.')],
 ['Yuri is the Russian form of George.',A('Jurijs ir vārda Juris (Georgs) forma.','Юрий — форма имени Георгий.','Yuri is a form of George.','Jurijus – vardo Jurgis forma.','Juri on nime Georg kuju.')],
 ['Nameda (printed in the dictionary as Namēda) is the Old Prussian personal name Nameda.',A('Nameda (arī Namēda) ir senprūšu personvārds Nameda.','Nameda (также Namēda) — древнепрусское личное имя Nameda.','Nameda (also Namēda) is the Old Prussian personal name Nameda.','Nameda (taip pat Namēda) – senasis prūsų asmenvardis Nameda.','Nameda (ka Namēda) on vanapreisi isikunimi Nameda.')],
 ['Irena is the West Slavic and Baltic form of the Greek name Eirene, literally “peace”; Lithuanian name dictionaries render it as “peace, calm”.',A('Irena ir grieķu vārda Eirene rietumslāvu un baltu forma — burtiski «miers», «klusums».','Irena — западнославянская и балтийская форма греческого имени Eirene, буквально «мир, покой».','Irena is the West Slavic and Baltic form of the Greek name Eirene, literally “peace, calm”.','Irena – vakarų slavų ir baltų graikiško vardo Eirene forma, pažodžiui „taika, ramybė“.','Irena on kreeka nime Eirene lääneslaavi ja balti kuju, sõna-sõnalt ‘rahu, vaikus’.')],
 ['Taiga comes from Latvian taiga, borrowed from Russian тайга.',A('Taiga cēlies no vārda taiga — ziemeļu skujkoku mežs.','Тайга происходит от слова «тайга» — северный хвойный лес.','Taiga comes from the word taiga, the northern coniferous forest.','Taiga kilęs iš žodžio taiga – šiaurės spygliuočių miškas.','Taiga pärineb sõnast taiga – põhjamaine okasmets.')],
 ['It is the feminine of the Roman family name Aemilius, which is derived from Latin aemulus, “rival”; Lithuanian name dictionaries render the sense as “spirited, unsurpassed”.',A('Tā ir romiešu dzimtas vārda Aemilius sieviešu forma, kas cēlies no latīņu aemulus — «sāncensis»; nozīmi atveido arī kā «dedzīga, nepārspēta».','Это женская форма римского родового имени Aemilius, от латинского aemulus — «соперник»; смысл передают и как «пылкая, непревзойдённая».','It is the feminine of the Roman family name Aemilius, which is derived from Latin aemulus, “rival”; the sense is also rendered as “spirited, unsurpassed”.','Tai moteriška romėnų giminės vardo Aemilius forma, kilusi iš lotynų aemulus („varžovas“); prasmė perteikiama ir kaip „karšta, nepralenkiama“.','See on Rooma suguvõsanime Aemilius naisvorm, ladina sõnast aemulus ‘rivaal’; tähendust antakse edasi ka kui ‘tulihingeline, ületamatu’.')],
 ['Viļa is a Russian pet form of Vilhelmīne.',A('Viļa ir vārda Vilhelmīne mīlvārds.','Виля — ласкательная форма имени Vilhelmīne.','Viļa is a pet form of Vilhelmīne.','Viļa – vardo Vilhelmīne maloninė forma.','Viļa on nime Vilhelmīne hellitusvorm.')],
 ['Birutė is a Lithuanian name which, according to Lithuanian name dictionaries, is formed from the verb birti, “to pour, to trickle”, with the diminutive suffix -ut-.',A('Birutė ir lietuviešu vārds, kas darināts no darbības vārda birti — «birt, tecēt» — ar pamazināmo piedēkli -ut-.','Birutė — литовское имя, образованное от глагола birti — «сыпаться, струиться» — с уменьшительным суффиксом -ut-.','Birutė is a Lithuanian name formed from the verb birti, “to pour, to trickle”, with the diminutive suffix -ut-.','Birutė – lietuviškas vardas, sudarytas iš veiksmažodžio birti su mažybine priesaga -ut-.','Birutė on leedu nimi, mis on moodustatud tegusõnast birti ‘pudenema, nirisema’ vähendusliitega -ut-.')],
 ['Igor is the Russian form of the Old Norse name Yngvarr, related to Swedish Ingvar.',A('Igors cēlies no senskandināvu vārda Yngvarr, kas radniecīgs zviedru Ingvar.','Игорь восходит к древнескандинавскому имени Yngvarr, родственному шведскому Ingvar.','Igor goes back to the Old Norse name Yngvarr, related to Swedish Ingvar.','Igoris kilęs iš senovės skandinavų vardo Yngvarr, giminingo švedų Ingvar.','Igor pärineb vanapõhja nimest Yngvarr, mis on sugulane rootsi nimega Ingvar.')],
 ['Latvian Igors follows the Russian form.',D],
 ['The actor Savely Kramarov bore the Russian form; his filmography includes two 1971 comedies, Gentlemen of Fortune and The Twelve Chairs, and Ivan Vasilievich Changes Profession of 1973.',A('Šo vārdu nesa aktieris Saveli Kramarovs; viņa filmogrāfijā ir 1971. gada komēdijas «Veiksmes kungi» un «Divpadsmit krēsli», kā arī 1973. gada «Ivans Vasiļjevičs maina profesiju».','Это имя носил актёр Савелий Крамаров; в его фильмографии — комедии 1971 года «Джентльмены удачи» и «Двенадцать стульев», а также «Иван Васильевич меняет профессию» 1973 года.','The actor Savely Kramarov bore the name; his filmography includes two 1971 comedies, Gentlemen of Fortune and The Twelve Chairs, and Ivan Vasilievich Changes Profession of 1973.','Šį vardą turėjo aktorius Saveli Kramarovas; jo filmografijoje – 1971 metų komedijos „Sėkmės džentelmenai“ ir „Dvylika kėdžių“ bei 1973 metų „Ivanas Vasiljevičius keičia profesiją“.','Seda nime kandis näitleja Saveli Kramarov; tema filmides on 1971. aasta komöödiad „Õnne härrasmehed“ ja „Kaksteist tooli“ ning 1973. aasta „Ivan Vassiljevitš vahetab ametit“.')],
 ['The name came to Russia with the Greek church calendar, and Latvian Gaļina and Galina are two spellings of the Russian form.',A('Vārds izplatījās ar grieķu baznīcas kalendāru; Gaļina un Galina ir divas tā rakstības latviešu valodā.','Имя распространилось с греческим церковным календарём; Gaļina и Galina — два латышских написания.','The name spread with the Greek church calendar, and Gaļina and Galina are two Latvian spellings of it.','Vardas paplito su graikų bažnyčios kalendoriumi; Gaļina ir Galina – dvi jo rašybos latvių kalboje.','Nimi levis kreeka kirikukalendriga; Gaļina ja Galina on selle kaks läti kirjapilti.')],
 ['Genrihs may be the Latvian form of Russian Genrikh, the Russian form of Heinrich, from Germanic words for “home” and “ruler”; this route is uncertain.',A('Genrihs varētu būt vārda Heinrihs forma; tas cēlies no ģermāņu vārdiem «mājas» un «valdnieks», taču šis ceļš nav drošs.','Генрихс, возможно, форма имени Heinrich, от германских слов «дом» и «правитель»; этот путь не вполне надёжен.','Genrihs may be a form of Heinrich, from Germanic words for “home” and “ruler”; this route is uncertain.','Genrihs galbūt yra Heinricho forma, iš germanų žodžių „namai“ ir „valdovas“; šis kelias neaiškus.','Genrihs võib olla nime Heinrich kuju, germaani sõnadest ‘kodu’ ja ‘valitseja’; see tee pole kindel.')],
 ['Aleksejs is the Latvian form of Russian Alexei, from the Greek name Alexios, closely related to Alexis.',A('Aleksejs cēlies no grieķu vārda Alexios, kas cieši radniecīgs Alexis.','Алексей восходит к греческому имени Alexios, близкому к Alexis.','Aleksejs comes from the Greek name Alexios, closely related to Alexis.','Aleksejs kilęs iš graikų vardo Alexios, artimo Alexis.','Aleksejs pärineb kreeka nimest Alexios, mis on lähedane nimele Alexis.')],
 ['Olimpiada (Olimpiāda in the dictionary) comes from Greek Olympias (genitive Olympiados), “the Olympic Games”.',A('Olimpiada (arī Olimpiāda) cēlies no grieķu Olympias (ģen. Olympiados) — «olimpiskās spēles».','Olimpiada (также Olimpiāda) восходит к греческому Olympias (род. п. Olympiados) — «Олимпийские игры».','Olimpiada (also Olimpiāda) comes from Greek Olympias (genitive Olympiados), “the Olympic Games”.','Olimpiada (taip pat Olimpiāda) kilusi iš graikų Olympias (kilm. Olympiados) – „olimpinės žaidynės“.','Olimpiada (ka Olimpiāda) pärineb kreeka sõnast Olympias (om. Olympiados) ‘olümpiamängud’.')],
 ['It is usually traced to two Germanic roots meaning “kin” and “woman”; Lithuanian name dictionaries give a similar reading but call the name Latin.',A('To parasti saista ar divām ģermāņu saknēm — «dzimta» un «sieviete»; ir arī skaidrojums, kas vārdu uzskata par latīnisku.','Его обычно возводят к двум германским корням — «род» и «женщина»; есть и толкование, считающее имя латинским.','It is usually traced to two Germanic roots meaning “kin” and “woman”; another reading calls the name Latin.','Paprastai jis siejamas su dviem germanų šaknimis – „giminė“ ir „moteris“; kitas aiškinimas vardą laiko lotynišku.','Seda seostatakse tavaliselt kahe germaani tüvega – ‘suguvõsa’ ja ‘naine’; teise seletuse järgi on nimi ladina päritolu.')],
 ['Sava is a Russian pet form of Savēlijs (Saveliy) or comes from Aramaic sābā, “old man, grandfather”.',A('Sava ir vārda Savēlijs mīlvārds vai cēlies no arāmiešu sābā — «sirmgalvis, vectēvs».','Сава — ласкательная форма имени Savēlijs или восходит к арамейскому sābā — «старец, дед».','Sava is a pet form of Savēlijs or comes from Aramaic sābā, “old man, grandfather”.','Sava – vardo Savēlijs maloninė forma arba kilęs iš aramėjų sābā („senolis, senelis“).','Sava on nime Savēlijs hellitusvorm või pärineb aramea sõnast sābā ‘vanamees, vanaisa’.')],
 ['Olga is the Russian form of the Old Norse name Helga.',A('Olga cēlies no senskandināvu vārda Helga.','Ольга восходит к древнескандинавскому имени Helga.','Olga goes back to the Old Norse name Helga.','Olga kilusi iš senovės skandinavų vardo Helga.','Olga pärineb vanapõhja nimest Helga.')],
 ['From Russian the name passed into the Latvian and Estonian calendars as Olga.',A('Latviešu un igauņu kalendāros vārds ienāca formā Olga.','В латышский и эстонский календари имя вошло в форме Olga.','The name entered the Latvian and Estonian calendars as Olga.','Į latvių ir estų kalendorius vardas pateko forma Olga.','Läti ja eesti kalendrisse jõudis nimi kujul Olga.')],
 ['Rimars (Rimārs in the dictionary) is formed from Old High German rīchi, “mighty”, and māri, “famous”.',A('Rimars (arī Rimārs) darināts no senaugšvācu rīchi — «varens» — un māri — «slavens».','Rimars (также Rimārs) образовано от древневерхненемецких rīchi — «могучий» — и māri — «славный».','Rimars (also Rimārs) is formed from Old High German rīchi, “mighty”, and māri, “famous”.','Rimars (taip pat Rimārs) sudarytas iš senosios aukštaičių vokiečių rīchi („galingas“) ir māri („garsus“).','Rimars (ka Rimārs) on moodustatud vanaülemsaksa sõnadest rīchi ‘vägev’ ja māri ‘kuulus’.')],
 ['Oleg is the Russian form of the Old Norse name Helgi, linked with a word meaning “holy, sacred”; the same Helgi gave Scandinavian Helge.',A('Oļegs cēlies no senskandināvu vārda Helgi, ko saista ar vārdu «svēts»; no tā paša Helgi ir skandināvu Helge.','Олег восходит к древнескандинавскому имени Helgi, связанному со словом «святой»; от того же Helgi — скандинавское Helge.','Oleg goes back to the Old Norse name Helgi, linked with a word meaning “holy, sacred”; the same Helgi gave Scandinavian Helge.','Olegas kilęs iš senovės skandinavų vardo Helgi, siejamo su žodžiu „šventas“; iš to paties Helgi – skandinavų Helge.','Oleg pärineb vanapõhja nimest Helgi, mida seostatakse sõnaga ‘püha’; samast Helgist on ka skandinaavia Helge.')],
 ['Lithuanian name dictionaries render the sense as “heard and blessed by God”.',A('Nozīmi atveido kā «Dieva uzklausīta un svētīta».','Смысл передают как «услышанная и благословлённая Богом».','The sense is rendered as “heard and blessed by God”.','Prasmė perteikiama kaip „Dievo išklausyta ir palaiminta“.','Tähendust antakse edasi kui ‘Jumala kuuldud ja õnnistatud’.')],
 ['Ruda (Rūda in the dictionary) is the feminine of Rūdolfs.',A('Ruda (arī Rūda) ir vārda Rūdolfs sieviešu forma.','Ruda (также Rūda) — женская форма имени Rūdolfs.','Ruda (also Rūda) is the feminine of Rūdolfs.','Ruda (taip pat Rūda) – moteriška vardo Rūdolfs forma.','Ruda (ka Rūda) on nime Rūdolfs naisvorm.')],
 ['Sveta is a Russian short form of Svetlana, a name linked with Russian svet, “light”, and svetly, “bright”.',A('Sveta ir vārda Svetlana saīsinājums; Svetlana saistās ar slāvu vārdiem «gaisma» un «gaišs».','Света — сокращение имени Светлана, связанного со славянскими словами «свет» и «светлый».','Sveta is a short form of Svetlana, a name linked with Slavic words for “light” and “bright”.','Sveta – vardo Svetlana trumpinys; Svetlana siejama su slavų žodžiais „šviesa“ ir „šviesus“.','Sveta on nime Svetlana lühend; Svetlanat seostatakse slaavi sõnadega ‘valgus’ ja ‘hele’.')],
 ['Nine Byzantine emperors bore the name, and two Russian tsars; Latvian Mihails follows the Russian form Mikhail.',A('Šo vārdu nesa deviņi Bizantijas imperatori.','Это имя носили девять византийских императоров.','Nine Byzantine emperors bore the name.','Šį vardą turėjo devyni Bizantijos imperatoriai.','Seda nime kandsid üheksa Bütsantsi keisrit.')],
 ['Ļubova comes from Russian lyubov’, “love”.',A('Ļubova cēlies no slāvu vārda «mīlestība».','Любовь — от славянского слова «любовь».','Ļubova comes from a Slavic word for “love”.','Ļubova kilusi iš slavų žodžio „meilė“.','Ļubova pärineb slaavi sõnast ‘armastus’.')],
 ['Quite separately, Ronya also occurs as a Russian pet form of Veronika, so the same sound can have different roots.',A('Pavisam atsevišķi Roņa sastopama arī kā vārda Veronika mīlvārds, tāpēc vienādai skaņai var būt dažādas saknes.','Совсем отдельно Роня встречается и как ласкательная форма имени Вероника, так что одно звучание может иметь разные корни.','Quite separately, Ronya also occurs as a pet form of Veronika, so the same sound can have different roots.','Visai atskirai Ronia pasitaiko ir kaip vardo Veronika maloninė forma, tad tas pats skambesys gali turėti skirtingas šaknis.','Täiesti eraldi esineb Ronja ka nime Veronika hellitusvormina, nii et samal kõlal võivad olla eri juured.')],
 ['Gilarijs is the Russian form of Hilārijs (Hilary).',A('Gilarijs ir vārda Hilārijs forma.','Gilarijs — форма имени Hilārijs (Иларий).','Gilarijs is a form of Hilārijs (Hilary).','Gilarijs – vardo Hilārijs forma.','Gilarijs on nime Hilārijs kuju.')],
 ['Latvian Nadežda follows the Russian form.',D],
 ['The dictionary calls those two forms phonetic formations, but does not document that origin for Vianda.',A('Tie abi ir fonētiski darinājumi, taču vārdam Vianda šāda cilme nav dokumentēta.','Обе эти формы — фонетические образования, но для Vianda такое происхождение не документировано.','Those two forms are phonetic formations, but that origin is not documented for Vianda.','Abi formos yra fonetiniai dariniai, bet vardui Vianda tokia kilmė nedokumentuota.','Mõlemad on häälikulised moodustised, kuid nimele Vianda pole sellist päritolu dokumenteeritud.')],
 ['The dictionary calls those two forms phonetic formations, but does not document that origin for Viāna.',A('Tie abi ir fonētiski darinājumi, taču vārdam Viāna šāda cilme nav dokumentēta.','Обе эти формы — фонетические образования, но для Viāna такое происхождение не документировано.','Those two forms are phonetic formations, but that origin is not documented for Viāna.','Abi formos yra fonetiniai dariniai, bet vardui Viāna tokia kilmė nedokumentuota.','Mõlemad on häälikulised moodustised, kuid nimele Viāna pole sellist päritolu dokumenteeritud.')],
 ['Zinovijs is the Belarusian and Russian form of Zinobijs, from Greek Zeus (genitive Zēnos) and bios, “life”.',A('Zinovijs ir vārda Zinobijs forma; tas cēlies no grieķu Zeus (ģen. Zēnos) un bios — «dzīve».','Zinovijs — форма имени Zinobijs, от греческих Zeus (род. п. Zēnos) и bios — «жизнь».','Zinovijs is a form of Zinobijs, from Greek Zeus (genitive Zēnos) and bios, “life”.','Zinovijs – vardo Zinobijs forma, iš graikų Zeus (kilm. Zēnos) ir bios („gyvenimas“).','Zinovijs on nime Zinobijs kuju, kreeka sõnadest Zeus (om. Zēnos) ja bios ‘elu’.')],
 ['Jevgeņijs is a Latvian rendering of the Russian form of Eižens; the family goes back to Greek eugenēs, “well-born, noble”.',A('Jevgeņijs ir viena no Eižena vārda saimes formām; saime iet atpakaļ uz grieķu eugenēs — «labi dzimis, dižciltīgs».','Jevgeņijs — одна из форм семейства имени Eižens; оно восходит к греческому eugenēs — «благородный».','Jevgeņijs is one of the forms of the Eižens family, which goes back to Greek eugenēs, “well-born, noble”.','Jevgeņijs – viena iš vardo Eižens šeimos formų; ji kyla iš graikų eugenēs („kilmingas“).','Jevgeņijs on üks nime Eižens pere kujusid; pere läheb tagasi kreeka sõnale eugenēs ‘õilis, suursugune’.')],
 ['Jevgēnija is a Latvian rendering of Russian Yevgeniya, alongside Jevgeņija, one of several Latvian spellings of the same Russian name; the family goes back to Greek eugenēs, “well-born, noble”.',A('Jevgēnija ir viena no vairākām šī vārda latviskajām rakstībām līdzās Jevgeņija; saime iet atpakaļ uz grieķu eugenēs — «labi dzimis, dižciltīgs».','Jevgēnija — одно из нескольких латышских написаний этого имени наряду с Jevgeņija; семейство восходит к греческому eugenēs — «благородный».','Jevgēnija is one of several Latvian spellings of the name, alongside Jevgeņija; the family goes back to Greek eugenēs, “well-born, noble”.','Jevgēnija – viena iš kelių šio vardo latviškų rašybų šalia Jevgeņija; šeima kyla iš graikų eugenēs („kilmingas“).','Jevgēnija on üks nime mitmest läti kirjapildist Jevgeņija kõrval; pere läheb tagasi kreeka sõnale eugenēs ‘õilis’.')],
 ['The spelling Jevgēnija appears in a 1993 table of Russian name renderings.',D],
 ['Jevgenijs is a Latvian rendering of Russian Yevgeny, alongside Jevgeņijs un Jevgēnijs, one of several Latvian spellings of the same Russian name; the family goes back to Greek eugenēs, “well-born, noble”.',A('Jevgenijs ir viena no vairākām šī vārda latviskajām rakstībām līdzās Jevgeņijs un Jevgēnijs; saime iet atpakaļ uz grieķu eugenēs — «labi dzimis, dižciltīgs».','Jevgenijs — одно из нескольких латышских написаний этого имени наряду с Jevgeņijs и Jevgēnijs; семейство восходит к греческому eugenēs — «благородный».','Jevgenijs is one of several Latvian spellings of the name, alongside Jevgeņijs and Jevgēnijs; the family goes back to Greek eugenēs, “well-born, noble”.','Jevgenijs – viena iš kelių šio vardo latviškų rašybų šalia Jevgeņijs ir Jevgēnijs; šeima kyla iš graikų eugenēs („kilmingas“).','Jevgenijs on üks nime mitmest läti kirjapildist Jevgeņijsi ja Jevgēnijsi kõrval; pere läheb tagasi kreeka sõnale eugenēs ‘õilis’.')],
 ['Jevgēnijs is a Latvian rendering of Russian Yevgeny, alongside Jevgeņijs, one of several Latvian spellings of the same Russian name; the family goes back to Greek eugenēs, “well-born, noble”.',A('Jevgēnijs ir viena no vairākām šī vārda latviskajām rakstībām līdzās Jevgeņijs; saime iet atpakaļ uz grieķu eugenēs — «labi dzimis, dižciltīgs».','Jevgēnijs — одно из нескольких латышских написаний этого имени наряду с Jevgeņijs; семейство восходит к греческому eugenēs — «благородный».','Jevgēnijs is one of several Latvian spellings of the name, alongside Jevgeņijs; the family goes back to Greek eugenēs, “well-born, noble”.','Jevgēnijs – viena iš kelių šio vardo latviškų rašybų šalia Jevgeņijs; šeima kyla iš graikų eugenēs („kilmingas“).','Jevgēnijs on üks nime mitmest läti kirjapildist Jevgeņijsi kõrval; pere läheb tagasi kreeka sõnale eugenēs ‘õilis’.')],
 ['The spelling Jevgēnijs appears in a 1993 table of Russian name renderings.',D],
 ['Jevgēņijs is a Latvian rendering of Russian Yevgeny, alongside Jevgeņijs, one of several Latvian spellings of the same Russian name; the family goes back to Greek eugenēs, “well-born, noble”.',A('Jevgēņijs ir viena no vairākām šī vārda latviskajām rakstībām līdzās Jevgeņijs; saime iet atpakaļ uz grieķu eugenēs — «labi dzimis, dižciltīgs».','Jevgēņijs — одно из нескольких латышских написаний этого имени наряду с Jevgeņijs; семейство восходит к греческому eugenēs — «благородный».','Jevgēņijs is one of several Latvian spellings of the name, alongside Jevgeņijs; the family goes back to Greek eugenēs, “well-born, noble”.','Jevgēņijs – viena iš kelių šio vardo latviškų rašybų šalia Jevgeņijs; šeima kyla iš graikų eugenēs („kilmingas“).','Jevgēņijs on üks nime mitmest läti kirjapildist Jevgeņijsi kõrval; pere läheb tagasi kreeka sõnale eugenēs ‘õilis’.')],
 ['Jevģēnijs is a Latvian rendering of Russian Yevgeny, alongside Jevgenijs, Jevgeņijs un Jevgēnijs, one of several Latvian spellings of the same Russian name; the family goes back to Greek eugenēs, “well-born, noble”.',A('Jevģēnijs ir viena no vairākām šī vārda latviskajām rakstībām līdzās Jevgenijs, Jevgeņijs un Jevgēnijs; saime iet atpakaļ uz grieķu eugenēs — «labi dzimis, dižciltīgs».','Jevģēnijs — одно из нескольких латышских написаний этого имени наряду с Jevgenijs, Jevgeņijs и Jevgēnijs; семейство восходит к греческому eugenēs — «благородный».','Jevģēnijs is one of several Latvian spellings of the name, alongside Jevgenijs, Jevgeņijs and Jevgēnijs; the family goes back to Greek eugenēs, “well-born, noble”.','Jevģēnijs – viena iš kelių šio vardo latviškų rašybų šalia Jevgenijs, Jevgeņijs ir Jevgēnijs; šeima kyla iš graikų eugenēs („kilmingas“).','Jevģēnijs on üks nime mitmest läti kirjapildist Jevgenijsi, Jevgeņijsi ja Jevgēnijsi kõrval; pere läheb tagasi kreeka sõnale eugenēs ‘õilis’.')],
 ['A 2025 study of given names in Latvia over the last century compared the popularity of these four spellings in Latgale using historical statistics, showing that they long existed side by side.',A('Vēsturiskā statistika rāda, ka Latgalē šīs četras rakstības ilgi pastāvēja līdzās.','Историческая статистика показывает, что в Латгалии эти четыре написания долго существовали рядом.','Historical statistics show that in Latgale these four spellings long existed side by side.','Istorinė statistika rodo, kad Latgaloje šios keturios rašybos ilgai gyvavo greta.','Ajalooline statistika näitab, et Latgales püsisid need neli kirjapilti kaua kõrvuti.')],
 ...[['Eugenijs','Eugēnijs'],['Euģenijs','Eugēnijs'],['Euģēnijs','Eugēnijs'],['Evgenijs','Eugēnijs'],['Evgēnijs','Eugēnijs'],['Evģenijs','Eugēnijs'],['Evģēnijs','Eugēnijs'],['Jevgēņija','Jevgeņija'],['Jevģenija','Jevgeņija'],['Jevģēnija','Jevgeņija'],['Jevģenijs','Jevgeņijs'],['Jevženija','Jevgeņija'],['Jevžēnija','Jevgeņija']].map(([n,b])=>eug(n,b)),
 ['The dictionary tentatively compares Vikars with Latin vicarius, deputy or helper.',A('Vikars piesardzīgi salīdzināms ar latīņu vicarius — «vietnieks, palīgs».','Vikars осторожно сопоставляют с латинским vicarius — «заместитель, помощник».','Vikars is tentatively compared with Latin vicarius, deputy or helper.','Vikars atsargiai lyginamas su lotynų vicarius („pavaduotojas, padėjėjas“).','Vikarsi võrreldakse ettevaatlikult ladina sõnaga vicarius ‘asetäitja, abiline’.')],
 ['The dictionary tentatively compares Landa with Jolanda and also mentions a sound-based formation.',A('Landa piesardzīgi salīdzināma ar Jolanda; iespējams arī, ka tā darināta pēc skanējuma.','Landa осторожно сопоставляют с Jolanda; возможно и образование по звучанию.','Landa is tentatively compared with Jolanda; a sound-based formation is also possible.','Landa atsargiai lyginama su Jolanda; galimas ir darinys pagal skambesį.','Landat võrreldakse ettevaatlikult nimega Jolanda; võimalik on ka kõla järgi loodud nimi.')],
 ["Beta is still being checked between two routes named in Siliņš's dictionary: Beāte, or Bete as a short form of Elizabete.",A('Beta var būt cēlusies no Beāte vai no Bete kā Elizabetes saīsinājuma.','Beta может происходить от Beāte или от Bete как сокращения Elizabete.','Beta may come either from Beāte or from Bete as a short form of Elizabete.','Beta gali būti kilusi iš Beāte arba iš Bete kaip Elizabetės trumpinio.','Beta võib pärineda nimest Beāte või nimest Bete kui Elizabete lühendist.')],
 ['A 2006 manual of English names in Latvian renders English Beth, a short form of Elizabeth, as Beta; this supports the Elizabete route for that rendering but does not exclude Beāte for other bearers.',A('Angļu Beth (Elizabetes saīsinājums) latviski tiek atveidots kā Beta; tas atbalsta Elizabetes ceļu, bet neizslēdz Beāti.','Английское Beth (сокращение Elizabeth) по-латышски передаётся как Beta; это поддерживает путь через Elizabete, но не исключает Beāte.','English Beth, a short form of Elizabeth, is rendered in Latvian as Beta; this supports the Elizabete route but does not exclude Beāte.','Angliškas Beth (Elizabeth trumpinys) latviškai perteikiamas kaip Beta; tai remia Elizabetės kelią, bet neatmeta Beāte.','Inglise Beth (Elizabethi lühend) antakse läti keeles edasi kui Beta; see toetab Elizabete teed, kuid ei välista Beātet.')],
 ['Dictionary forms with long ī and short i are not automatically interchangeable; each spelling needs its own direct evidence.',D],
 ['The dictionary cautiously compares Vigars with Wighard, explained through Old High German wīg, battle, and hart, firm.',A('Vigars piesardzīgi salīdzināms ar Wighard, ko skaidro ar senaugšvācu wīg — «kauja» — un hart — «stingrs».','Vigars осторожно сопоставляют с Wighard — от древневерхненемецких wīg «битва» и hart «твёрдый».','Vigars is cautiously compared with Wighard, explained through Old High German wīg, battle, and hart, firm.','Vigars atsargiai lyginamas su Wighard, aiškinamu senosios aukštaičių vokiečių wīg („kova“) ir hart („tvirtas“).','Vigarsi võrreldakse ettevaatlikult nimega Wighard, mida seletatakse vanaülemsaksa sõnadega wīg ‘lahing’ ja hart ‘kindel’.')],
 ['The dictionary refers Vigda to Vigdis with a question mark.',A('Vigda, iespējams, saistāma ar Vigdis.','Vigda, возможно, связана с Vigdis.','Vigda is possibly linked with Vigdis.','Vigda galbūt siejama su Vigdis.','Vigda võib olla seotud nimega Vigdis.')],
 ['The dictionary cautiously compares Vigeta with Vigita, but questions the connection.',A('Vigeta piesardzīgi salīdzināma ar Vigita, taču saikne ir apšaubāma.','Vigeta осторожно сопоставляют с Vigita, но связь сомнительна.','Vigeta is cautiously compared with Vigita, but the connection is doubtful.','Vigeta atsargiai lyginama su Vigita, tačiau ryšys abejotinas.','Vigetat võrreldakse ettevaatlikult nimega Vigita, kuid seos on kahtlane.')],
 ['The dictionary cautiously compares Vigija with Vigilija, but questions the connection.',A('Vigija piesardzīgi salīdzināma ar Vigilija, taču saikne ir apšaubāma.','Vigija осторожно сопоставляют с Vigilija, но связь сомнительна.','Vigija is cautiously compared with Vigilija, but the connection is doubtful.','Vigija atsargiai lyginama su Vigilija, tačiau ryšys abejotinas.','Vigijat võrreldakse ettevaatlikult nimega Vigilija, kuid seos on kahtlane.')],
 ['The dictionary cautiously compares Vigita with Viga / Ligita, but questions the connection.',A('Vigita piesardzīgi salīdzināma ar Viga vai Ligita, taču saikne ir apšaubāma.','Vigita осторожно сопоставляют с Viga или Ligita, но связь сомнительна.','Vigita is cautiously compared with Viga or Ligita, but the connection is doubtful.','Vigita atsargiai lyginama su Viga ar Ligita, tačiau ryšys abejotinas.','Vigitat võrreldakse ettevaatlikult nimedega Viga või Ligita, kuid seos on kahtlane.')],
 ['The catalogue says this exact spelling was not found in the dictionary.',D],
 ['The catalogue does not find exact Vigorts in the dictionary.',D],
 ['The shared dictionary entry compares Vigurds with Wigwart, but marks the comparison with a question mark.',A('Vigurds piesardzīgi salīdzināms ar Wigwart.','Vigurds осторожно сопоставляют с Wigwart.','Vigurds is tentatively compared with Wigwart.','Vigurds atsargiai lyginamas su Wigwart.','Vigurdsi võrreldakse ettevaatlikult nimega Wigwart.')],
 ['The catalogue does not find it in the dictionary.',D],
 ['The catalogue says exact Zeltiņa was not found on the relevant dictionary page.',D],
 ['Vilora is the Latvian form of Russian Vilora (Вилора), a Soviet name of the 1920s–1930s made from the initials of a phrase naming Lenin as organiser of the revolution.',A('Vilora ir 20. gadsimta 20.–30. gadu padomju laika vārds, darināts no frāzes sākumburtiem, kas Ļeņinu sauc par revolūcijas organizētāju.','Вилора — советское имя 1920–1930-х годов, составленное из начальных букв фразы, называющей Ленина организатором революции.','Vilora is a Soviet-era name of the 1920s–1930s made from the initials of a phrase naming Lenin as organiser of the revolution.','Vilora – sovietmečio XX a. 3–4 dešimtmečio vardas, sudarytas iš frazės, Leniną vadinančios revoliucijos organizatoriumi, pirmųjų raidžių.','Vilora on 1920.–1930. aastate nõukogude nimi, mis on tehtud Leninit revolutsiooni korraldajaks nimetava fraasi algustähtedest.')],
 ['The dictionary material connects Zigrīds with the Sigrīda family, but its derivation remains unverified.',A('Zigrīds tiek saistīts ar Sigrīdas vārdu saimi, taču tā atvasinājums nav pārbaudīts.','Zigrīds связывают с семейством имени Sigrīda, но его образование не проверено.','Zigrīds is connected with the Sigrīda family, but its derivation remains unverified.','Zigrīds siejamas su Sigrīdos vardų šeima, tačiau jo darybą nepatikrinta.','Zigrīdsi seostatakse nime Sigrīda perega, kuid selle tuletus on kontrollimata.')],
 ['The dictionary material connects Zigda with the Sigrīda family, but its derivation remains unverified.',A('Zigda tiek saistīta ar Sigrīdas vārdu saimi, taču tās atvasinājums nav pārbaudīts.','Zigda связывают с семейством имени Sigrīda, но её образование не проверено.','Zigda is connected with the Sigrīda family, but its derivation remains unverified.','Zigda siejama su Sigrīdos vardų šeima, tačiau jos daryba nepatikrinta.','Zigdat seostatakse nime Sigrīda perega, kuid selle tuletus on kontrollimata.')],
 ['The dictionary material gives no single secure explanation for this form.',A('Šai formai nav viena droša skaidrojuma.','Единого надёжного объяснения этой формы нет.','There is no single secure explanation for this form.','Šiai formai nėra vieno patikimo paaiškinimo.','Sellele kujule pole üht kindlat seletust.')],
 ['The checked Latvian rendering of Андриан is Andriāns with a long ā, so the short-a spelling is not yet documented by a rendering record or dictionary entry.',A('Ierastā latviskā forma ir Andriāns ar garo ā; rakstība ar īso a vēl nav dokumentēta.','Привычная латышская форма — Andriāns с долгим ā; написание с кратким a пока не документировано.','The usual Latvian form is Andriāns with a long ā; the short-a spelling is not yet documented.','Įprasta latviška forma – Andriāns su ilguoju ā; rašyba su trumpuoju a dar nedokumentuota.','Tavaline läti kuju on pika ā-ga Andriāns; lühikese a-ga kirjapilt pole veel dokumenteeritud.')],
 ['Andriāns is the Latvian form of Russian Andrian, a folk form of Adrian, from Latin Adrianus, “a man from the town of Adria”; less securely, it is also explained as a blend of Andrejs and Adriāns.',A('Andriāns ir vārda Adrians tautas forma; tas cēlies no latīņu Adrianus — «vīrs no Adrijas pilsētas»; mazāk droši to skaidro arī kā Andreja un Adriāna sapludinājumu.','Andriāns — народная форма имени Adrian, от латинского Adrianus — «человек из города Адрия»; менее надёжно его объясняют и как слияние Andrejs и Adriāns.','Andriāns is a folk form of Adrian, from Latin Adrianus, “a man from the town of Adria”; less securely, it is also explained as a blend of Andrejs and Adriāns.','Andriāns – liaudiška vardo Adrian forma, iš lotynų Adrianus („vyras iš Adrijos miesto“); mažiau patikimai aiškinamas ir kaip Andrejs ir Adriāns sąlydis.','Andriāns on nime Adrian rahvapärane kuju, ladina nimest Adrianus ‘Adria linna mees’; vähem kindlalt seletatakse seda ka nimede Andrejs ja Adriāns liitena.')],
 ['Petrovsky’s 1966 Russian dictionary records Андриян as a folk form of Адриан, but no checked Latvian rendering record or dictionary entry gives Andrijans as a given name.',A('Andrijan ir vārda Adrian tautas forma, taču Andrijans kā latviešu personvārds nav dokumentēts.','Андриян — народная форма имени Адриан, но Andrijans как латышское имя не документировано.','Andriyan is a folk form of Adrian, but Andrijans is not documented as a Latvian given name.','Andrijan – liaudiška vardo Adrian forma, bet Andrijans kaip latvių vardas nedokumentuotas.','Andrijan on nime Adrian rahvapärane kuju, kuid Andrijans pole läti eesnimena dokumenteeritud.')],
 ['Androns is the Latvian form of Russian and Ukrainian Andron, a colloquial form of Andronik, from Greek anēr (genitive andros), “man”, and nikē, “victory”.',A('Androns ir vārda Androniks sarunvalodas forma; tas cēlies no grieķu anēr (ģen. andros) — «vīrs» — un nikē — «uzvara».','Androns — разговорная форма имени Andronik, от греческих anēr (род. п. andros) — «муж» — и nikē — «победа».','Androns is a colloquial form of Andronik, from Greek anēr (genitive andros), “man”, and nikē, “victory”.','Androns – šnekamoji vardo Andronik forma, iš graikų anēr (kilm. andros, „vyras“) ir nikē („pergalė“).','Androns on nime Andronik kõnekeelne kuju, kreeka sõnadest anēr (om. andros) ‘mees’ ja nikē ‘võit’.')],
 ['Varvara is the Russian form of Barbara and belongs to the Barbara family, from Greek barbaros, “foreigner, speaker of another language”; in the feminine name it is usually rendered “foreign woman”.',A('Varvara pieder Barbaras vārdu saimei, kas cēlusies no grieķu barbaros — «svešinieks, citas valodas runātājs»; sieviešu vārdā to parasti atveido kā «svešzemniece».','Варвара относится к семейству имени Барбара, от греческого barbaros — «чужеземец, говорящий на другом языке»; в женском имени это обычно передают как «чужеземка».','Varvara belongs to the Barbara family, from Greek barbaros, “foreigner, speaker of another language”; in the feminine name it is usually rendered “foreign woman”.','Varvara priklauso Barboros vardų šeimai, kilusiai iš graikų barbaros („svetimšalis, kalbantis kita kalba“); moters varde paprastai perteikiama kaip „svetimšalė“.','Varvara kuulub nime Barbara perre, kreeka sõnast barbaros ‘võõramaalane, teise keele kõneleja’; naisenimes antakse see tavaliselt edasi kui ‘võõramaa naine’.')],
 ['Latvian Vsevolods renders the Russian form.',D],
 ['Nikandrs is the Latvian form of Russian Nikandr, from Greek Nikandros: nikē, “victory”, and anēr (genitive andros), “man”.',A('Nikandrs cēlies no grieķu Nikandros: nikē — «uzvara» — un anēr (ģen. andros) — «vīrs».','Nikandrs восходит к греческому Nikandros: nikē — «победа» — и anēr (род. п. andros) — «муж».','Nikandrs comes from Greek Nikandros: nikē, “victory”, and anēr (genitive andros), “man”.','Nikandrs kilęs iš graikų Nikandros: nikē („pergalė“) ir anēr (kilm. andros, „vyras“).','Nikandrs pärineb kreeka nimest Nikandros: nikē ‘võit’ ja anēr (om. andros) ‘mees’.')],
 ['Ļusja is a Russian pet form of Lūcija and Ludmila.',A('Ļusja ir vārdu Lūcija un Ludmila mīlvārds.','Люся — ласкательная форма имён Lūcija и Ludmila.','Ļusja is a pet form of Lūcija and Ludmila.','Ļusja – vardų Lūcija ir Ludmila maloninė forma.','Ļusja on nimede Lūcija ja Ludmila hellitusvorm.')],
 ['Artemijs is the Latvian form of Russian Artemiy.',A('Artemijs ir grieķu vārda Artemios forma.','Artemijs — форма греческого имени Artemios.','Artemijs is a form of Greek Artemios.','Artemijs – graikiško vardo Artemios forma.','Artemijs on kreeka nime Artemios kuju.')],
 ['Dictionaries list it alongside craft words such as rotkalis (“jewellery maker”), nažkalis (“knife-smith”) and biskalis (“weapon-smith”).',A('Tas pieder pie amatu vārdiem, piemēram, rotkalis, nažkalis un biskalis.','Оно стоит в одном ряду с названиями ремёсел, например rotkalis («ювелир»), nažkalis («ножовщик») и biskalis («оружейник»).','It belongs with craft words such as rotkalis (“jewellery maker”), nažkalis (“knife-smith”) and biskalis (“weapon-smith”).','Jis priklauso amatų žodžiams, pavyzdžiui, rotkalis („juvelyras“), nažkalis („peilininkas“) ir biskalis („ginklakalys“).','See kuulub ametinimetuste hulka nagu rotkalis ‘ehtemeister’, nažkalis ‘noasepp’ ja biskalis ‘relvasepp’.')],
 ['The masculine and feminine pair Radvilas/Radvilė is already recorded in the Lithuanian spelling dictionary of 1948.',A('Vīriešu un sieviešu vārdu pāris Radvilas/Radvilė ir pierakstīts jau 1948. gadā.','Мужская и женская пара Radvilas/Radvilė зафиксирована уже в 1948 году.','The masculine and feminine pair Radvilas/Radvilė is already recorded in 1948.','Vyriško ir moteriško vardo pora Radvilas/Radvilė užfiksuota jau 1948 metais.','Mehe- ja naisenime paar Radvilas/Radvilė on kirja pandud juba 1948. aastal.')],
 ['Vaidutis is among the suffix-derived forms added to the 2003 edition of the Lithuanian name-origin dictionary.',A('Vaidutis ir ar piedēkli darināta forma.','Vaidutis — форма, образованная с суффиксом.','Vaidutis is a suffix-derived form.','Vaidutis – priesaginė forma.','Vaidutis on liitega tuletatud kuju.')],
 ['The first part, al-, is linked with “all, every” (Lithuanian name dictionaries compare aliai vienas, “every single one”), and the second, gird-, with the verb girdėti, “to hear”, and the noun girdas, “news, rumour”.',A('Pirmo daļu al- saista ar «viss, ikviens» (sal. aliai vienas — «visi līdz vienam»), bet otro gird- — ar darbības vārdu girdėti — «dzirdēt» — un lietvārdu girdas — «ziņa, valoda».','Первую часть al- связывают с «весь, каждый» (ср. aliai vienas — «все до единого»), а вторую gird- — с глаголом girdėti — «слышать» — и существительным girdas — «весть, молва».','The first part, al-, is linked with “all, every” (compare aliai vienas, “every single one”), and the second, gird-, with the verb girdėti, “to hear”, and the noun girdas, “news, rumour”.','Pirmoji dalis al- siejama su „visas, kiekvienas“ (plg. aliai vienas), o antroji gird- – su veiksmažodžiu girdėti ir daiktavardžiu girdas.','Esimest osa al- seostatakse tähendusega ‘kõik, iga’ (vrd aliai vienas ‘kõik viimseni’), teist osa gird- tegusõnaga girdėti ‘kuulma’ ja nimisõnaga girdas ‘sõnum, kuuldus’.')],
 ['Agota is a traditional Lithuanian name; the 2003 edition of the name dictionary also added its everyday diminutives.',A('Agota ir tradicionāls lietuviešu vārds ar daudziem ikdienas mīlvārdiem.','Agota — традиционное литовское имя с множеством бытовых уменьшительных форм.','Agota is a traditional Lithuanian name with many everyday diminutives.','Agota – tradicinis lietuviškas vardas, turintis daug kasdienių mažybinių formų.','Agota on traditsiooniline leedu nimi, millel on palju igapäevaseid hellitusvorme.')],
 ['Aivaras is a borrowed name that was added to the expanded Lithuanian name dictionary in 2003.',A('Aivaras ir aizgūts vārds.','Aivaras — заимствованное имя.','Aivaras is a borrowed name.','Aivaras – skolinys.','Aivaras on laennimi.')],
 ['Pakerys’s 2009 study explicitly discusses Gómantas: some authors connect go- with goti while others decline to identify its origin.',A('Daļa pētnieku saista sākumu go- ar goti, citi tā cilmi nenosaka.','Часть исследователей связывает начало go- с goti, другие не берутся определить его происхождение.','Some connect go- with goti, while others decline to identify its origin.','Vieni pradžią go- sieja su goti, kiti jos kilmės nenustato.','Osa seostab algust go- sõnaga goti, teised ei määra selle päritolu.')],
 ['As with Antanas, Lithuanian name dictionaries explain it from a Greek word meaning “happy, joyful”.',A('Tāpat kā Antanas, to skaidro ar grieķu vārdu, kas nozīmē «laimīgs, priecīgs».','Как и Antanas, его объясняют из греческого слова со значением «счастливый, радостный».','As with Antanas, it is explained from a Greek word meaning “happy, joyful”.','Kaip ir Antanas, jis aiškinamas iš graikų žodžio, reiškiančio „laimingas, džiugus“.','Nagu Antanast, seletatakse seda kreeka sõnaga, mis tähendab ‘õnnelik, rõõmus’.')],
 ['It is built from the Slavic stems kaziti, “to destroy”, and mirŭ, “peace, world”, so Lithuanian name dictionaries translate it as “destroyer of the world”.',A('Tas darināts no slāvu celmiem kaziti — «iznīcināt» — un mirŭ — «miers, pasaule»; nozīmi atveido kā «miera graujējs».','Оно образовано от славянских основ kaziti — «разрушать» — и mirŭ — «мир»; смысл передают как «разрушитель мира».','It is built from the Slavic stems kaziti, “to destroy”, and mirŭ, “peace, world”, so the sense is rendered as “destroyer of the world”.','Jis sudarytas iš slavų kamienų kaziti („griauti“) ir mirŭ („taika, pasaulis“), todėl verčiamas „pasaulio griovėjas“.','See on moodustatud slaavi tüvedest kaziti ‘hävitama’ ja mirŭ ‘rahu, maailm’, seega ‘maailma hävitaja’.')],
 ['At its root lies the Greek sophia, “wisdom”, and this is exactly how Lithuanian name dictionaries explain Zofija: from the Greek Sophia.',A('Tā pamatā ir grieķu sophia — «gudrība».','В его основе — греческое sophia, «мудрость».','At its root lies the Greek sophia, “wisdom”.','Jo pagrindas – graikų sophia („išmintis“).','Selle aluseks on kreeka sophia ‘tarkus’.')],
 ['Page 94 of the 2010 study gives Gražvydas among Graž- names; Pakerys prints the accented form Grãžvydas.',A('Gražvydas pieder pie vārdiem ar Graž-; uzsvērtā forma ir Grãžvydas.','Gražvydas относится к именам на Graž-; ударная форма — Grãžvydas.','Gražvydas belongs with the Graž- names; the accented form is Grãžvydas.','Gražvydas priklauso Graž- vardams; kirčiuota forma – Grãžvydas.','Gražvydas kuulub Graž-algusega nimede hulka; rõhumärgiga kuju on Grãžvydas.')],
 ['The Old German Hadewig combines hadu, “battle”, and wig, “war”; Lithuanian name dictionaries sum up the sense as “struggle”.',A('Senvācu Hadewig apvieno hadu — «kauja» — un wig — «karš»; nozīmi rezumē kā «cīņa».','Древненемецкое Hadewig соединяет hadu — «битва» — и wig — «война»; смысл передают как «борьба».','The Old German Hadewig combines hadu, “battle”, and wig, “war”; the sense is summed up as “struggle”.','Senovės vokiečių Hadewig jungia hadu („kova“) ir wig („karas“); prasmė apibendrinama kaip „kova“.','Vanasaksa Hadewig ühendab sõnad hadu ‘lahing’ ja wig ‘sõda’; tähendus võetakse kokku kui ‘võitlus’.')],
 ['Ekaterina is the Russian form of Katherine, from Greek Aikaterine, whose origin is debated; the meaning “pure” came later.',A('Ekaterina ir vārda Katrīna forma, no grieķu Aikaterine, kura cilme ir strīdīga; nozīme «tīrā» radās vēlāk.','Екатерина — форма имени Катерина, от греческого Aikaterine, происхождение которого спорно; значение «чистая» появилось позже.','Ekaterina is a form of Katherine, from Greek Aikaterine, whose origin is debated; the meaning “pure” came later.','Ekaterina – vardo Kotryna forma, iš graikų Aikaterine, kurio kilmė ginčytina; reikšmė „tyra“ atsirado vėliau.','Ekaterina on nime Katariina kuju, kreeka nimest Aikaterine, mille päritolu on vaieldav; tähendus ‘puhas’ tekkis hiljem.')],
 ['Page 198 of the 1983 study gives Anastazija as a personal name corresponding to Anastasia.',A('Anastazija atbilst vārdam Anastasia.','Anastazija соответствует имени Anastasia.','Anastazija corresponds to Anastasia.','Anastazija atitinka vardą Anastasia.','Anastazija vastab nimele Anastasia.')],
 ['Page 92 of the 2011 study gives Sanrimė as Sánrimė alongside masculine Sánrimas.',A('Sanrimė (Sánrimė) ir sieviešu pāris vīriešu vārdam Sánrimas.','Sanrimė (Sánrimė) — женская пара к мужскому Sánrimas.','Sanrimė (Sánrimė) is the feminine counterpart of masculine Sánrimas.','Sanrimė (Sánrimė) – vyriško vardo Sánrimas moteriškoji pora.','Sanrimė (Sánrimė) on mehenime Sánrimas naispaariline.')],
 ['It was once listed only as a surname, but the expanded name dictionary of 2003 includes it as a given name.',A('Agrāk tas bija pazīstams tikai kā uzvārds, bet tagad tiek lietots arī kā vārds.','Раньше оно было известно лишь как фамилия, теперь употребляется и как имя.','It was once known only as a surname, but is now also used as a given name.','Anksčiau jis buvo žinomas tik kaip pavardė, o dabar vartojamas ir kaip vardas.','Varem tunti seda ainult perekonnanimena, nüüd kasutatakse ka eesnimena.')],
 ['Lithuanian name dictionaries put the sense as a wish that God may add another child to this newborn.',A('Nozīmi skaidro kā vēlējumu, lai Dievs šim jaundzimušajam pievienotu vēl kādu bērnu.','Смысл объясняют как пожелание, чтобы Бог прибавил к этому новорождённому ещё одного ребёнка.','The sense is a wish that God may add another child to this newborn.','Prasmė – linkėjimas, kad Dievas prie šio naujagimio pridėtų dar vieną vaiką.','Tähendus on soov, et Jumal lisaks sellele vastsündinule veel ühe lapse.')],
 ['Page 228 of the 1983 study gives Kristijonas as the equivalent of Christian.',A('Kristijonas atbilst vārdam Christian.','Kristijonas соответствует имени Christian.','Kristijonas is the equivalent of Christian.','Kristijonas atitinka vardą Christian.','Kristijonas vastab nimele Christian.')],
 ['Lithuanian name dictionaries explain Pranas exactly this way: a shortening of Pranciškus, of Germanic origin, “Frankish”.',A('Pranas ir Pranciškus saīsinājums; vārds ir ģermāņu cilmes — «franks».','Pranas — сокращение имени Pranciškus германского происхождения — «франкский».','Pranas is a shortening of Pranciškus, of Germanic origin, “Frankish”.','Pranas – Pranciškaus trumpinys; vardas germaniškos kilmės („frankas“).','Pranas on nime Pranciškus lühend; nimi on germaani päritolu, ‘frankide’.')],
 ['In a study of rare names among emigrants’ children, Normantas is suggested as a possible basis for the short Normas, which might also be a masculine counterpart of the feminine Norma.',A('Normantas varētu būt saīsinājuma Normas pamatā; Normas var būt arī sieviešu vārda Norma vīriešu pāris.','Normantas, возможно, лежит в основе краткого Normas, которое может быть и мужской парой к женскому Norma.','Normantas may be the basis of the short Normas, which might also be a masculine counterpart of the feminine Norma.','Normantas galbūt yra trumpinio Normas pagrindas; Normas gali būti ir moteriško vardo Norma vyriškoji pora.','Normantas võib olla lühikese nime Normas alus; Normas võib olla ka naisenime Norma meespaariline.')],
 ['Lithuanian name dictionaries read it as “standing with glory”.',A('Nozīmi atveido kā «stāvošs slavā».','Смысл передают как «стоящий во славе».','It is read as “standing with glory”.','Prasmė perteikiama kaip „stovintis su šlove“.','Seda tõlgendatakse kui ‘kuulsuses seisev’.')],
 ['Lithuanian name dictionaries connect it with the verb kęsti, “to endure, to bear”, and read it as “the enduring one”.',A('To saista ar darbības vārdu kęsti — «izturēt, paciest» — un atveido kā «izturīgais».','Его связывают с глаголом kęsti — «терпеть, выносить» — и толкуют как «стойкий».','It is connected with the verb kęsti, “to endure, to bear”, and read as “the enduring one”.','Jis siejamas su veiksmažodžiu kęsti ir aiškinamas kaip „ištvermingasis“.','Seda seostatakse tegusõnaga kęsti ‘taluma, kannatama’ ja tõlgendatakse kui ‘vastupidav’.')],
 ['Rimtenis is among the suffix-derived forms added to the 2003 edition of the Lithuanian name-origin dictionary.',A('Rimtenis ir ar piedēkli darināta forma.','Rimtenis — форма, образованная с суффиксом.','Rimtenis is a suffix-derived form.','Rimtenis – priesaginė forma.','Rimtenis on liitega tuletatud kuju.')],
 ['The exact-form explanation still needs dictionary verification.',D],
 ['Besides the Greco-Persian reading “rich man”, Lithuanian name dictionaries also mention the Lithuanian root dar- (daryti, “to do, to make”) and the surname of a transatlantic aviator.',A('Līdzās grieķu-persiešu skaidrojumam «bagāts vīrs» min arī lietuviešu sakni dar- (daryti — «darīt») un transatlantiskā lidotāja uzvārdu.','Помимо греко-персидского толкования «богатый человек», упоминают и литовский корень dar- (daryti — «делать») и фамилию трансатлантического лётчика.','Besides the Greco-Persian reading “rich man”, the Lithuanian root dar- (daryti, “to do, to make”) and the surname of a transatlantic aviator are also mentioned.','Šalia graikų-persų aiškinimo „turtingas vyras“ minima ir lietuvių šaknis dar- (daryti) bei transatlantinio lakūno pavardė.','Kreeka-pärsia seletuse ‘rikas mees’ kõrval mainitakse ka leedu tüve dar- (daryti ‘tegema’) ja Atlandi ookeani ületanud lenduri perekonnanime.')],
 ['It is listed as a feminine name, next to the masculine Gražvydas, in a Lithuanian–German dictionary published in 1968; the 1964 calendar has the different spelling Grožvilė on 20 December.',A('Tā kā sieviešu vārds līdzās vīriešu Gražvydas pierakstīta 1968. gadā; 1964. gada kalendārā 20. decembrī ir cita rakstība — Grožvilė.','Как женское имя рядом с мужским Gražvydas оно записано в 1968 году; в календаре 1964 года на 20 декабря другое написание — Grožvilė.','It is recorded as a feminine name, next to the masculine Gražvydas, in 1968; the 1964 calendar has the different spelling Grožvilė on 20 December.','Kaip moters vardas šalia vyriško Gražvydas užrašytas 1968 metais; 1964 metų kalendoriuje gruodžio 20 d. yra kita rašyba – Grožvilė.','Naisenimena mehenime Gražvydas kõrval on see kirja pandud 1968. aastal; 1964. aasta kalendris on 20. detsembril teine kirjapilt Grožvilė.')],
 ['Lithuanian name dictionaries render the sense as “she who has become glorious”.',A('Nozīmi atveido kā «tā, kas kļuvusi slavena».','Смысл передают как «та, что стала славной».','The sense is rendered as “she who has become glorious”.','Prasmė perteikiama kaip „ta, kuri tapo šlovinga“.','Tähendust antakse edasi kui ‘see, kes on saanud kuulsaks’.')],
 ['The feminine form is found in many Slavic languages, and in Lithuanian it has the short form Stasė, which the dictionaries explain as a shortening of this same name.',A('Sieviešu forma sastopama daudzās slāvu valodās, bet lietuviešu valodā tai ir saīsinājums Stasė.','Женская форма встречается во многих славянских языках, а в литовском у неё есть краткая форма Stasė.','The feminine form is found in many Slavic languages, and in Lithuanian it has the short form Stasė.','Moteriška forma randama daugelyje slavų kalbų, o lietuvių kalboje ji turi trumpinį Stasė.','Naisvorm esineb paljudes slaavi keeltes ja leedu keeles on sellel lühivorm Stasė.')],
 ['Page 228 of the 1983 study gives Ksavera as a personal name corresponding to Xaveria.',A('Ksavera atbilst vārdam Xaveria.','Ksavera соответствует имени Xaveria.','Ksavera corresponds to Xaveria.','Ksavera atitinka vardą Xaveria.','Ksavera vastab nimele Xaveria.')],
 ['Page 240 of the 1983 study gives Olimpija in a separate personal-name entry.',D],
 ['Sinkevičiūtė’s 2017 study of the stem gerd- argues that it is a secondary spelling variant of gird-, which arose when Lithuanian names were written down in Ruthenian and Polish documents; it discusses the surnames Gerdvila and Gerdvilas, not Gerdvilė itself.',A('Celmu gerd- uzskata par celma gird- sekundāru rakstības variantu, kas radās, lietuviešu vārdus pierakstot rutēņu un poļu dokumentos.','Основу gerd- считают вторичным вариантом написания основы gird-, возникшим при записи литовских имён в русинских и польских документах.','The stem gerd- is considered a secondary spelling variant of gird-, which arose when Lithuanian names were written down in Ruthenian and Polish documents.','Kamienas gerd- laikomas antriniu kamieno gird- rašybos variantu, atsiradusiu lietuvių vardus užrašant rusėnų ir lenkų dokumentuose.','Tüve gerd- peetakse tüve gird- teiseseks kirjavariandiks, mis tekkis leedu nimede kirjapanekul rusiini ja poola dokumentides.')],
 ['It is also recorded as a masculine name in a German–Lithuanian dictionary, next to the feminine Vaišvydė.',A('Tas pierakstīts arī kā vīriešu vārds līdzās sieviešu Vaišvydė.','Оно записано и как мужское имя рядом с женским Vaišvydė.','It is also recorded as a masculine name, next to the feminine Vaišvydė.','Jis užrašytas ir kaip vyro vardas šalia moteriško Vaišvydė.','See on kirja pandud ka mehenimena naisenime Vaišvydė kõrval.')],
 ['It is listed as a personal name in a Lithuanian–German dictionary published in 1968.',A('Kā personvārds tas pierakstīts 1968. gadā.','Как личное имя оно записано в 1968 году.','It is recorded as a personal name in 1968.','Kaip asmenvardis jis užrašytas 1968 metais.','Isikunimena on see kirja pandud 1968. aastal.')],
 ['Pakerys’s study discusses the exact feminine form.',D],
 ['Page 98 of the 2011 study gives Eiviltė in comparison with Eivilta.',A('Eiviltė ir salīdzināma ar Eivilta.','Eiviltė сопоставима с Eivilta.','Eiviltė is comparable with Eivilta.','Eiviltė lygintina su Eivilta.','Eiviltė on võrreldav nimega Eivilta.')],
 ['Lithuanian name dictionaries link it with the Slavic root vladi, “rule!”, and the full name goes back to Old Slavic Voldislavŭ, from volděti, “to rule”, and slava, “glory”.',A('To saista ar slāvu sakni vladi — «valdi!» —, bet pilnais vārds iet atpakaļ uz senslāvu Voldislavŭ, no volděti — «valdīt» — un slava — «slava».','Его связывают со славянским корнем vladi — «владей!», — а полное имя восходит к старославянскому Voldislavŭ, от volděti — «владеть» — и slava — «слава».','It is linked with the Slavic root vladi, “rule!”, and the full name goes back to Old Slavic Voldislavŭ, from volděti, “to rule”, and slava, “glory”.','Jis siejamas su slavų šaknimi vladi („valdyk!“), o visas vardas kyla iš senosios slavų Voldislavŭ: volděti („valdyti“) ir slava („šlovė“).','Seda seostatakse slaavi tüvega vladi ‘valitse!’, täisnimi aga läheb tagasi vanaslaavi nimele Voldislavŭ: volděti ‘valitsema’ ja slava ‘kuulsus’.')],
 ['The name has no established dictionary meaning; it is counted among the women’s names that were proposed as reconstructed ancient Estonian names, together with Virve, Maimu, Leida, Salme and Vaike.',A('Vārdam nav nostiprinājušās nozīmes; tas pieder pie sieviešu vārdiem, kas ierosināti kā atjaunoti seni igauņu vārdi, līdzās Virve, Maimu, Leida, Salme un Vaike.','У имени нет устоявшегося значения; его относят к женским именам, предложенным как восстановленные древнеэстонские, вместе с Virve, Maimu, Leida, Salme и Vaike.','The name has no established meaning; it is counted among the women’s names that were proposed as reconstructed ancient Estonian names, together with Virve, Maimu, Leida, Salme and Vaike.','Vardas neturi nusistovėjusios reikšmės; jis priskiriamas moterų vardams, pasiūlytiems kaip atkurti senieji estų vardai, kartu su Virve, Maimu, Leida, Salme ir Vaike.','Nimel pole kinnistunud tähendust; see kuulub naisenimede hulka, mida pakuti taastatud vanade eesti nimedena koos nimedega Virve, Maimu, Leida, Salme ja Vaike.')],
 ['It is not derived from Taima or Taimi, although a dictionary lists them together.',A('Tas nav atvasināts no Taima vai Taimi, lai gan tos mēdz minēt kopā.','Оно не происходит от Taima или Taimi, хотя их иногда называют вместе.','It is not derived from Taima or Taimi, although they are sometimes listed together.','Jis nėra kilęs iš Taima ar Taimi, nors jie kartais minimi kartu.','See ei ole tuletatud nimedest Taima või Taimi, kuigi neid mõnikord koos nimetatakse.')],
 ['Viilup appears in the 1936 list of recommended Estonian names as a name from Wiedemann’s dictionary.',A('Viilup ir 1936. gada ieteicamo igauņu vārdu sarakstā kā sens vārds.','Viilup есть в списке рекомендованных эстонских имён 1936 года как старое имя.','Viilup appears in the 1936 list of recommended Estonian names as an old name.','Viilup yra 1936 metų rekomenduojamų estų vardų sąraše kaip senas vardas.','Viilup esineb 1936. a. soovitusnimestikus vana nimena.')],
 ['They may also come from Elias and its Russian form Ilja.',A('Tie var būt cēlušies arī no Elias un tā formas Ilja.','Они могут происходить и от Elias и его формы Ilja.','They may also come from Elias and its form Ilja.','Jie gali būti kilę ir iš Elias bei jo formos Ilja.','Need võivad pärineda ka nimest Elias ja selle kujust Ilja.')],
 ['The sixteenth-century Polish survey of Livonia records the form Pap, and a nineteenth-century dictionary gives Paabu and Paapu as women’s names.',A('16. gadsimta poļu Livonijas revīzijā pierakstīta forma Pap, bet 19. gadsimtā Paabu un Paapu zināmi kā sieviešu vārdi.','В польской ревизии Ливонии XVI века записана форма Pap, а в XIX веке Paabu и Paapu известны как женские имена.','The sixteenth-century Polish survey of Livonia records the form Pap, and in the nineteenth century Paabu and Paapu are known as women’s names.','XVI a. lenkų Livonijos revizijoje užrašyta forma Pap, o XIX a. Paabu ir Paapu žinomi kaip moterų vardai.','16. sajandi Poola Liivimaa revisjonis on kirjas kuju Pap, 19. sajandil on Paabu ja Paapu tuntud naisenimedena.')],
 ['Mägiste (1936) lists it, with a question mark, as an old name from documents.',A('1936. gadā tas ar jautājuma zīmi minēts kā sens vārds no dokumentiem.','В 1936 году оно с вопросительным знаком названо старым именем из документов.','In 1936 it was listed, with a question mark, as an old name from documents.','1936 metais jis su klaustuku nurodytas kaip senas vardas iš dokumentų.','1936. aastal nimetati seda küsimärgiga vanaks dokumendinimeks.')],
 ['In their study of names in school books, Liina Hergauk and Ingrid Mald found that Tõnu and Rein were the most frequent men’s names in Estonian primers from 1940 to 1985, followed by Tiit, Ants, Villu, Enn and Alo.',A('Igauņu ābeču tekstos no 1940. līdz 1985. gadam visbiežākie vīriešu vārdi bija Tõnu un Rein, aiz tiem Tiit, Ants, Villu, Enn un Alo.','В эстонских букварях 1940–1985 годов чаще всего встречались мужские имена Tõnu и Rein, затем Tiit, Ants, Villu, Enn и Alo.','In Estonian primers from 1940 to 1985, Tõnu and Rein were the most frequent men’s names, followed by Tiit, Ants, Villu, Enn and Alo.','1940–1985 metų estų elementoriuose dažniausi vyrų vardai buvo Tõnu ir Rein, po jų – Tiit, Ants, Villu, Enn ir Alo.','Eesti aabitsates 1940–1985 olid kõige sagedasemad mehenimed Tõnu ja Rein, neile järgnesid Tiit, Ants, Villu, Enn ja Alo.')],
 ['Elias is a Hebrew name meaning “God is the Lord”; the Russian form is Ilya.',A('Elias ir ebreju vārds ar nozīmi «Dievs ir Kungs».','Элиас — еврейское имя со значением «Бог есть Господь».','Elias is a Hebrew name meaning “God is the Lord”.','Elias – hebrajiškas vardas, reiškiantis „Dievas yra Viešpats“.','Elias on heebrea nimi tähendusega ‘Jumal on Issand’.')],
 ['Marve is an Estonian variant of Marta, which came through the Russian form Marfa; Marta is the name of the sister of Lazarus in the Gospels.',A('Marve ir vārda Marta igauņu variants; Marta Evaņģēlijos ir Lācara māsa.','Marve — эстонский вариант имени Марта; в Евангелиях Марта — сестра Лазаря.','Marve is an Estonian variant of Marta; Marta is the name of the sister of Lazarus in the Gospels.','Marve – estiškas vardo Morta variantas; Evangelijose Morta – Lozoriaus sesuo.','Marve on nime Marta eesti teisend; evangeeliumides on Marta Laatsaruse õde.')],
 ['Marvi is an Estonian variant of Marta, which came through the Russian form Marfa; Marta is the name of the sister of Lazarus in the Gospels.',A('Marvi ir vārda Marta igauņu variants; Marta Evaņģēlijos ir Lācara māsa.','Marvi — эстонский вариант имени Марта; в Евангелиях Марта — сестра Лазаря.','Marvi is an Estonian variant of Marta; Marta is the name of the sister of Lazarus in the Gospels.','Marvi – estiškas vardo Morta variantas; Evangelijose Morta – Lozoriaus sesuo.','Marvi on nime Marta eesti teisend; evangeeliumides on Marta Laatsaruse õde.')],
 ['Kaubi (Kaupo) is one of the few old Estonian names from historical documents to which a whole study has been devoted (M.',A('Kaubi (Kaupo) ir viens no retajiem seniem igauņu vārdiem no vēstures dokumentiem, kas izpētīts īpaši rūpīgi.','Kaubi (Kaupo) — одно из немногих старых эстонских имён из исторических документов, изученных особенно подробно.','Kaubi (Kaupo) is one of the few old Estonian names from historical documents that has been studied in particular detail.','Kaubi (Kaupo) – vienas iš nedaugelio senųjų estų vardų iš istorinių dokumentų, ištirtų ypač išsamiai.','Kaubi (Kaupo) on üks väheseid ajaloodokumentidest tuntud vanu eesti nimesid, mida on eriti põhjalikult uuritud.')],
 ['A study of names in Estonian primers and maths textbooks found that between 1940 and 1985 many maths books were translated from Russian and their characters were given names familiar to Estonian children.',A('No 1940. līdz 1985. gadam daudzas matemātikas grāmatas tika tulkotas, un to tēliem deva igauņu bērniem pazīstamus vārdus.','В 1940–1985 годах многие учебники математики были переводными, и их персонажам давали привычные эстонским детям имена.','Between 1940 and 1985 many maths books were translations, and their characters were given names familiar to Estonian children.','1940–1985 metais daug matematikos vadovėlių buvo versti, o jų veikėjams duoti estų vaikams įprasti vardai.','Aastatel 1940–1985 olid paljud matemaatikaõpikud tõlked ja nende tegelastele anti eesti lastele tuttavaid nimesid.')],
 ['Alve may be connected with Alviine and Alvi: the Estonian dictionary entries list it among related names.',A('Alve var būt saistīta ar Alviine un Alvi; tie ir radniecīgi vārdi.','Alve может быть связана с Alviine и Alvi; это родственные имена.','Alve may be connected with Alviine and Alvi, which are related names.','Alve gali būti susijusi su Alviine ir Alvi; tai giminingi vardai.','Alve võib olla seotud nimedega Alviine ja Alvi, mis on suguluses.')],
 ['The historical study’s row Helmok, Helmus — Helmo, Helmke — Helmut does not contain Helmu.',D],
 ["Helmur is still being checked between two placements in Edgar Rajandi's 1966 name book: as a further development of Helmut, and as a variant listed beside Elmur under Elmar.",A('Helmur var būt gan Helmut tālāka attīstība, gan variants līdzās Elmur pie vārda Elmar.','Helmur может быть и дальнейшим развитием Helmut, и вариантом рядом с Elmur при имени Elmar.','Helmur may be either a further development of Helmut or a variant beside Elmur under Elmar.','Helmur gali būti ir tolesnė Helmut raida, ir variantas šalia Elmur prie vardo Elmar.','Helmur võib olla nii Helmuti edasiarendus kui ka teisend Elmuri kõrval nime Elmar all.')],
 ['Säsil might be compared with Cécile or Cecilia, but the origin explanation found is user-submitted rather than a verified dictionary entry.',A('Säsil varētu salīdzināt ar Cécile vai Cecilia, taču šī cilme nav pārbaudīta.','Säsil можно сопоставить с Cécile или Cecilia, но это происхождение не проверено.','Säsil might be compared with Cécile or Cecilia, but this origin is unverified.','Säsil galima palyginti su Cécile ar Cecilia, bet ši kilmė nepatikrinta.','Säsilit võib võrrelda nimedega Cécile või Cecilia, kuid see päritolu on kontrollimata.')],
 ['Niina is the Estonian form of the Russian name Nina.',A('Niina ir vārda Nina igauņu forma.','Niina — эстонская форма имени Нина.','Niina is the Estonian form of the name Nina.','Niina – estiška vardo Nina forma.','Niina on nime Nina eesti kuju.')],
 ['The exact form Osmar is documented: Rajandi marks it as a German name recorded in Tallinn birth registers of 1930–1950.',A('Pati Osmar forma ir dokumentēta: tas ir vācu vārds, kas pierakstīts Tallinas dzimšanas reģistros 1930.–1950. gadā.','Сама форма Osmar документирована: это немецкое имя, записанное в таллинских метрических книгах 1930–1950 годов.','The exact form Osmar is documented as a German name recorded in Tallinn birth registers of 1930–1950.','Pati Osmar forma dokumentuota: tai vokiškas vardas, užrašytas Talino gimimo registruose 1930–1950 metais.','Kirjapilt Osmar on dokumenteeritud saksa nimena, mis on kirja pandud Tallinna sünniregistrites aastatel 1930–1950.')],
 ['Niina is the Estonian form of the Russian name Nina, and Estonian Wikipedia describes it as a name of Russian origin.',A('Niina ir vārda Nina igauņu forma.','Niina — эстонская форма имени Нина.','Niina is the Estonian form of the name Nina.','Niina – estiška vardo Nina forma.','Niina on nime Nina eesti kuju.')],
 ['The dictionary calls those two forms phonetic formations, but does not document that origin for {name}.',A('Tie abi ir fonētiski darinājumi, taču vārdam {name} šāda cilme nav dokumentēta.','Обе эти формы — фонетические образования, но для {name} такое происхождение не документировано.','Those two forms are phonetic formations, but that origin is not documented for {name}.','Abi formos yra fonetiniai dariniai, bet vardui {name} tokia kilmė nedokumentuota.','Mõlemad on häälikulised moodustised, kuid nimele {name} pole sellist päritolu dokumenteeritud.')],
 ...['Eugēnijs','Jevgeņija','Jevgeņijs'].map(b=>[`{name} could be compared with the documented dictionary form ${b}.`,cmp('{name}',b)]),
 ['Iva is a form of Ivonna and Ieva; it is also linked with Russian iva, “willow”, and Old High German iwa, “bow”.',A('Iva ir vārdu Ivonna un Ieva forma; to saista arī ar slāvu iva — «vītols» — un senaugšvācu iwa — «loks».','Iva — форма имён Ivonna и Ieva; её связывают и со славянским iva — «ива» — и древневерхненемецким iwa — «лук».','Iva is a form of Ivonna and Ieva; it is also linked with Slavic iva, “willow”, and Old High German iwa, “bow”.','Iva – vardų Ivonna ir Ieva forma; ji siejama ir su slavų iva („gluosnis“) bei senosios aukštaičių vokiečių iwa („lankas“).','Iva on nimede Ivonna ja Ieva kuju; seda seostatakse ka slaavi sõnaga iva ‘paju’ ja vanaülemsaksa sõnaga iwa ‘vibu’.')],
 ['Agnija is compared with Russian Agniya, a form of Agnes; the family goes back to Greek hagnos, “chaste”.',A('Agnija ir vārda Agnese forma; saime iet atpakaļ uz grieķu hagnos — «šķīsts».','Agnija — форма имени Агнесса; семейство восходит к греческому hagnos — «чистый».','Agnija is a form of Agnes; the family goes back to Greek hagnos, “chaste”.','Agnija – vardo Agnė forma; šeima kyla iš graikų hagnos („skaistus“).','Agnija on nime Agnes kuju; nimepere pärineb kreeka sõnast hagnos ‘karske’.')],
 ['Darja is the Belarusian, Russian and Ukrainian form of Dārija.',A('Darja ir vārda Dārija slāvu forma.','Darja — славянская форма имени Dārija.','Darja is a Slavic form of Dārija.','Darja – slaviška vardo Dārija forma.','Darja on nime Dārija slaavi kuju.')],
 ['Vadims is tentatively compared with Old Russian vaditi, “to incite, urge”; that is only a proposal, and the exact origin has not been explained.',A('Vadims piesardzīgi salīdzināms ar seno slāvu vaditi — «kūdīt, mudināt»; tas ir tikai pieņēmums, un precīza cilme nav izskaidrota.','Вадимс осторожно сопоставляют со старославянским vaditi — «подстрекать, побуждать»; это лишь предположение, точное происхождение не объяснено.','Vadims is tentatively compared with old Slavic vaditi, “to incite, urge”; that is only a proposal, and the exact origin has not been explained.','Vadims atsargiai lyginamas su senąja slavų vaditi („kurstyti, raginti“); tai tik prielaida, tiksli kilmė nepaaiškinta.','Vadimsi võrreldakse ettevaatlikult vanaslaavi sõnaga vaditi ‘õhutama, ässitama’; see on vaid oletus ja täpne päritolu on seletamata.')],
 ['Georgijs stands beside Georgs; Russian Georgiy goes back to George and Greek geōrgos, “farmer”.',A('Georgijs stāv līdzās Georgs; abi iet atpakaļ uz Juri un grieķu geōrgos — «zemkopis».','Georgijs стоит рядом с Georgs; оба восходят к Георгию и греческому geōrgos — «земледелец».','Georgijs stands beside Georgs; both go back to George and Greek geōrgos, “farmer”.','Georgijs stovi šalia Georgs; abu kyla iš Jurgio ir graikų geōrgos („žemdirbys“).','Georgijs seisab Georgsi kõrval; mõlemad lähevad tagasi Georgile ja kreeka sõnale geōrgos ‘põllumees’.')],
 ['Through the Orthodox tradition the name became familiar in Russia as Yuri, and Latvian Jurijs renders exactly that form.',A('Pareizticīgo tradīcijā vārds Austrumeiropā kļuva pazīstams kā Jurijs.','В православной традиции имя стало известно в Восточной Европе как Юрий.','Through the Orthodox tradition the name became familiar in Eastern Europe as Yuri.','Stačiatikių tradicijoje vardas Rytų Europoje išgarsėjo kaip Jurijus.','Õigeusu traditsioonis sai nimi Ida-Euroopas tuntuks kujul Juri.')],
 ['Iraida is a Russian and Spanish form of Herais; its exact route into Latvian is not known, and Iraīda with a long ī is a separate entry.',A('Iraida ir vārda Herais forma; tā precīzais ceļš latviešu valodā nav zināms, un Iraīda ar garo ī ir atsevišķs vārds.','Iraida — форма имени Herais; её точный путь в латышский язык неизвестен, а Iraīda с долгим ī — отдельное имя.','Iraida is a form of Herais; its exact route into Latvian is not known, and Iraīda with a long ī is a separate entry.','Iraida – vardo Herais forma; tikslus jos kelias į latvių kalbą nežinomas, o Iraīda su ilguoju ī – atskiras vardas.','Iraida on nime Herais kuju; selle täpne tee läti keelde pole teada ning pika ī-ga Iraīda on eraldi nimi.')],
 ['Through the Orthodox calendar it reached Russia and from there the Latvian calendar.',A('Ar pareizticīgo kalendāru tas izplatījās un nonāca arī latviešu kalendārā.','С православным календарём оно распространилось и попало в латышский календарь.','It spread with the Orthodox calendar and reached the Latvian calendar.','Su stačiatikių kalendoriumi jis paplito ir pateko į latvių kalendorių.','Õigeusu kalendriga see levis ja jõudis ka läti kalendrisse.')],
 ['Gļebs is an old Russian personal name of Scandinavian origin; it is compared with Old Norse Gudleifr and Old Germanic Gutleib, without a literal meaning.',A('Gļebs ir sens skandināvu cilmes personvārds; to salīdzina ar senskandināvu Gudleifr un senģermāņu Gutleib, bez burtiskas nozīmes.','Глеб — старое личное имя скандинавского происхождения; его сопоставляют с древнескандинавским Gudleifr и древнегерманским Gutleib, без буквального значения.','Gļebs is an old personal name of Scandinavian origin; it is compared with Old Norse Gudleifr and Old Germanic Gutleib, without a literal meaning.','Gļebs – senas skandinaviškos kilmės asmenvardis; lyginamas su senovės skandinavų Gudleifr ir senovės germanų Gutleib, be pažodinės reikšmės.','Gļebs on vana skandinaavia päritolu isikunimi; seda võrreldakse vanapõhja nimega Gudleifr ja vanagermaani nimega Gutleib, sõnasõnalise tähenduseta.')],
 ['Lada is a short form of Vladislava; Russian lada means “beloved, dear”, and Lada is a goddess of marriage and love.',A('Lada ir vārda Vladislava saīsinājums; slāvu lada nozīmē «mīļā», un Lada ir laulības un mīlestības dieviete.','Лада — сокращение имени Владислава; славянское «лада» значит «милая», а Лада — богиня брака и любви.','Lada is a short form of Vladislava; Slavic lada means “beloved, dear”, and Lada is a goddess of marriage and love.','Lada – vardo Vladislava trumpinys; slavų lada reiškia „mieloji“, o Lada – santuokos ir meilės deivė.','Lada on nime Vladislava lühend; slaavi lada tähendab ‘kallis, armas’ ning Lada on abielu- ja armastusejumalanna.')],
 ['Latvian Maksims and Lithuanian Maksimas are forms of the same name as Russian Maksim.',A('Latviešu Maksims un lietuviešu Maksimas ir viena vārda — latīņu Maximus — formas.','Латышское Maksims и литовское Maksimas — формы одного имени, латинского Maximus.','Latvian Maksims and Lithuanian Maksimas are forms of the same name, Latin Maximus.','Latviškas Maksims ir lietuviškas Maksimas – to paties vardo, lotynų Maximus, formos.','Läti Maksims ja leedu Maksimas on sama nime, ladina Maximuse, kujud.')],
 ['Nils is a form of Nikolauss and Kornēlijs; the Russian name Nil comes from Latin Nilus, “the Nile”.',A('Nils ir vārdu Nikolauss un Kornēlijs forma; vārds Nil cēlies no latīņu Nilus — «Nīla».','Nils — форма имён Nikolauss и Kornēlijs; имя Нил восходит к латинскому Nilus — «Нил».','Nils is a form of Nikolauss and Kornēlijs; the name Nil comes from Latin Nilus, “the Nile”.','Nils – vardų Nikolauss ir Kornēlijs forma; vardas Nil kilęs iš lotynų Nilus („Nilas“).','Nils on nimede Nikolauss ja Kornēlijs kuju; nimi Nil pärineb ladina sõnast Nilus ‘Niilus’.')],
 ['It is known among several Slavic peoples, and the spelling Ludmila also renders Russian Lyudmila.',A('Tas ir pazīstams vairākām slāvu tautām.','Оно известно у нескольких славянских народов.','It is known among several Slavic peoples.','Jis žinomas keletui slavų tautų.','Nimi on tuntud mitme slaavi rahva seas.')],
 ['Savelijs corresponds to Russian Савелий; the international family is linked with Roman Sabellius and the Sabines, though other explanations exist and none is certain.',A('Vārda Savelijs starptautisko saimi saista ar romiešu Sabellius un sabīņiem, taču ir arī citi skaidrojumi, un neviens nav drošs.','Международное семейство имени Savelijs связывают с римским Sabellius и сабинянами, но есть и другие объяснения, и ни одно не надёжно.','Savelijs belongs to an international family linked with Roman Sabellius and the Sabines, though other explanations exist and none is certain.','Vardo Savelijs tarptautinė šeima siejama su romėnų Sabellius ir sabinais, bet yra ir kitų aiškinimų, nė vienas nėra tikras.','Savelijsi rahvusvahelist nimeperet seostatakse Rooma Sabelliuse ja sabiinidega, kuid on ka teisi seletusi ja ükski pole kindel.')],
 ['Savēlijs corresponds to Russian Савелий; the international family is linked with Roman Sabellius and the Sabines, though other explanations exist and none is certain.',A('Vārda Savēlijs starptautisko saimi saista ar romiešu Sabellius un sabīņiem, taču ir arī citi skaidrojumi, un neviens nav drošs.','Международное семейство имени Savēlijs связывают с римским Sabellius и сабинянами, но есть и другие объяснения, и ни одно не надёжно.','Savēlijs belongs to an international family linked with Roman Sabellius and the Sabines, though other explanations exist and none is certain.','Vardo Savēlijs tarptautinė šeima siejama su romėnų Sabellius ir sabinais, bet yra ir kitų aiškinimų, nė vienas nėra tikras.','Savēlijsi rahvusvahelist nimeperet seostatakse Rooma Sabelliuse ja sabiinidega, kuid on ka teisi seletusi ja ükski pole kindel.')],
 ['Galina is the Russian and Bulgarian feminine form of the Greek name Galenos, the same name borne by the physician Galen.',A('Galina ir grieķu vārda Galenos sieviešu forma; to pašu vārdu nesa ārsts Galēns.','Галина — женская форма греческого имени Galenos; это же имя носил врач Гален.','Galina is a feminine form of the Greek name Galenos, the same name borne by the physician Galen.','Galina – moteriška graikiško vardo Galenos forma; tą patį vardą turėjo gydytojas Galenas.','Galina on kreeka nime Galenos naisvorm; sama nime kandis arst Galenos.')],
 ['Gaļina is the Russian and Bulgarian feminine form of the Greek name Galenos, the same name borne by the physician Galen.',A('Gaļina ir grieķu vārda Galenos sieviešu forma; to pašu vārdu nesa ārsts Galēns.','Gaļina — женская форма греческого имени Galenos; это же имя носил врач Гален.','Gaļina is a feminine form of the Greek name Galenos, the same name borne by the physician Galen.','Gaļina – moteriška graikiško vardo Galenos forma; tą patį vardą turėjo gydytojas Galenas.','Gaļina on kreeka nime Galenos naisvorm; sama nime kandis arst Galenos.')],
 ['The name came to Russia with Christianity from Byzantium.',A('Vārds izplatījās līdz ar kristietību no Bizantijas.','Имя распространилось вместе с христианством из Византии.','The name spread with Christianity from Byzantium.','Vardas paplito kartu su krikščionybe iš Bizantijos.','Nimi levis koos ristiusuga Bütsantsist.')],
 ['Iļja is the Slavic form of Eliass used in Belarusian, Russian and Ukrainian; it goes back to Hebrew Ēlīyāhū, “Yahweh is my God”.',A('Iļja ir vārda Eliass slāvu forma; tas iet atpakaļ uz ebreju Ēlīyāhū — «Jahve ir mans Dievs».','Iļja — славянская форма имени Eliass; оно восходит к еврейскому Ēlīyāhū — «Яхве — мой Бог».','Iļja is the Slavic form of Eliass; it goes back to Hebrew Ēlīyāhū, “Yahweh is my God”.','Iļja – slaviška vardo Eliass forma; jis kyla iš hebrajų Ēlīyāhū („Jahvė – mano Dievas“).','Iļja on nime Eliass slaavi kuju; see läheb tagasi heebrea nimele Ēlīyāhū ‘Jahve on mu Jumal’.')],
 ['The name became popular, though never common, in twentieth-century Russia.',A('20. gadsimtā vārds kļuva populārs, kaut arī nekad nebija ļoti izplatīts.','В XX веке имя стало популярным, хотя и не было очень распространённым.','The name became popular, though never common, in the twentieth century.','XX amžiuje vardas tapo populiarus, nors niekada nebuvo labai paplitęs.','20. sajandil sai nimi populaarseks, kuigi see polnud kunagi väga levinud.')],
 ['Latvian Oļegs reproduces the Russian pronunciation.',null],
 ['Broņislavs is formed from Old Russian boroniti, “to protect”, and slava, “glory”.',A('Broņislavs darināts no senslāvu boroniti — «aizsargāt» — un slava — «slava».','Broņislavs образовано от старославянских boroniti — «защищать» — и slava — «слава».','Broņislavs is formed from Old Slavic boroniti, “to protect”, and slava, “glory”.','Broņislavs sudarytas iš senosios slavų boroniti („ginti“) ir slava („šlovė“).','Broņislavs on moodustatud vanaslaavi sõnadest boroniti ‘kaitsma’ ja slava ‘kuulsus’.')],
 ['Marfa is the Belarusian, Russian and Ukrainian form of Marta.',A('Marfa ir vārda Marta slāvu forma.','Marfa — славянская форма имени Марта.','Marfa is a Slavic form of Marta.','Marfa – slaviška vardo Morta forma.','Marfa on nime Marta slaavi kuju.')],
 ['Vera has several possible connections: Latin vera, “true”, Russian vera, “faith”, or the name Veronika.',A('Vērai ir vairākas iespējamas saiknes: latīņu vera — «patiesa», slāvu vera — «ticība» — vai vārds Veronika.','У имени Вера несколько возможных связей: латинское vera — «истинная», славянское «вера» или имя Вероника.','Vera has several possible connections: Latin vera, “true”, Slavic vera, “faith”, or the name Veronika.','Vera turi kelias galimas sąsajas: lotynų vera („tikra“), slavų vera („tikėjimas“) arba vardą Veronika.','Veral on mitu võimalikku seost: ladina vera ‘tõeline’, slaavi vera ‘usk’ või nimi Veronika.')],
 ['Christianity carried the name forward through Sergius, a fourth-century Roman officer martyred in Syria together with Bacchus; via the Orthodox calendar it became Russian Sergey, the model for the Latvian and Lithuanian forms.',A('Kristietība vārdu nesa tālāk ar Sergiju — 4. gadsimta romiešu virsnieku, kas kopā ar Bakhu cieta mocekļa nāvi Sīrijā; ar pareizticīgo kalendāru tas izplatījās tālāk.','Христианство пронесло имя через Сергия — римского офицера IV века, принявшего мученическую смерть в Сирии вместе с Вакхом; оно распространилось с православным календарём.','Christianity carried the name forward through Sergius, a fourth-century Roman officer martyred in Syria together with Bacchus; it spread further with the Orthodox calendar.','Krikščionybė vardą nešė toliau per Sergijų – IV a. romėnų karininką, kartu su Bakchu nukankintą Sirijoje; jis paplito su stačiatikių kalendoriumi.','Ristiusk kandis nime edasi Sergiuse kaudu – 4. sajandi Rooma ohvitser, kes suri koos Bacchusega märtrina Süürias; nimi levis edasi õigeusu kalendriga.')],
 ['It is linked with the Russian adjective svetly, “bright”, and the word svet, “light”; another explanation sees it as a translation of the church name Photina, from Greek phōs, “light”.',A('To saista ar slāvu īpašības vārdu svetly — «gaišs» — un vārdu svet — «gaisma»; cits skaidrojums to uzskata par baznīcas vārda Fotīna tulkojumu, no grieķu phōs — «gaisma».','Его связывают со славянским прилагательным «светлый» и словом «свет»; по другому объяснению, это перевод церковного имени Фотина, от греческого phōs — «свет».','It is linked with the Slavic adjective svetly, “bright”, and the word svet, “light”; another explanation sees it as a translation of the church name Photina, from Greek phōs, “light”.','Jis siejamas su slavų būdvardžiu svetly („šviesus“) ir žodžiu svet („šviesa“); kitas aiškinimas jį laiko bažnytinio vardo Fotina vertiniu, iš graikų phōs („šviesa“).','Seda seostatakse slaavi omadussõnaga svetly ‘hele’ ja sõnaga svet ‘valgus’; teise seletuse järgi on see kirikunime Photina tõlge, kreeka sõnast phōs ‘valgus’.')],
 ['Latvian Svjatoslavs reflects the Russian pronunciation.',null],
 ['Vjačeslavs is formed from Old Russian vjače, “more”, and slava, “glory”.',A('Vjačeslavs darināts no senslāvu vjače — «vairāk» — un slava — «slava».','Vjačeslavs образовано от старославянских vjače — «более» — и slava — «слава».','Vjačeslavs is formed from Old Slavic vjače, “more”, and slava, “glory”.','Vjačeslavs sudarytas iš senosios slavų vjače („daugiau“) ir slava („šlovė“).','Vjačeslavs on moodustatud vanaslaavi sõnadest vjače ‘rohkem’ ja slava ‘kuulsus’.')],
 ['In Russian it became Dmitriy, the model for Latvian Dmitrijs and Dimitrijs.',A('Latviešu Dmitrijs un Dimitrijs ir šī vārda formas.','Латышские Dmitrijs и Dimitrijs — формы этого имени.','Latvian Dmitrijs and Dimitrijs are forms of this name.','Latviški Dmitrijs ir Dimitrijs – šio vardo formos.','Läti Dmitrijs ja Dimitrijs on selle nime kujud.')],
 ['Kira is the Russian feminine form of Kir, that is, Cyrus.',A('Kira ir vārda Kirs, t. i., Kīrs, sieviešu forma.','Кира — женская форма имени Кир.','Kira is a feminine form of Kir, that is, Cyrus.','Kira – moteriška vardo Kir, t. y. Kyras, forma.','Kira on nime Kir ehk Kyros naisvorm.')],
 ['Mira is a short form of Miroslava, Miranda, Elmīra or Mirabella; many Russian women’s names end in -mira.',A('Mira ir vārdu Miroslava, Miranda, Elmīra vai Mirabella saīsinājums; daudzi slāvu sieviešu vārdi beidzas ar -mira.','Мира — сокращение имён Мирослава, Миранда, Эльмира или Мирабелла; многие славянские женские имена оканчиваются на -мира.','Mira is a short form of Miroslava, Miranda, Elmīra or Mirabella; many Slavic women’s names end in -mira.','Mira – vardų Miroslava, Miranda, Elmīra ar Mirabella trumpinys; daug slavų moterų vardų baigiasi -mira.','Mira on nimede Miroslava, Miranda, Elmīra või Mirabella lühend; paljud slaavi naisenimed lõpevad -mira-ga.')],
 ['Ninele is a Russian name: the name Lenin read backwards.',A('Ninele ir padomju laika vārds — Ļeņina vārds, lasīts no otra gala.','Нинель — имя советского времени: имя Ленин, прочитанное наоборот.','Ninele is a Soviet-era name: the name Lenin read backwards.','Ninelė – sovietmečio vardas: Lenino vardas, perskaitytas atbulai.','Ninele on nõukogude aja nimi – Lenini nimi tagurpidi loetuna.')],
 ['Jevgenija is a spelling of Jevgeņija with n instead of ņ; through Jevgeņija and the masculine Jevgeņijs it belongs with Russian Yevgeniya and Yevgeny; the family goes back to Greek eugenēs, “well-born, noble”.',A('Jevgenija ir Jevgeņijas rakstība ar n, nevis ņ; saimes pamatā ir grieķu eugenēs — «labi dzimis, cēls».','Jevgenija — написание имени Jevgeņija с n вместо ņ; семейство восходит к греческому eugenēs — «благородный».','Jevgenija is a spelling of Jevgeņija with n instead of ņ; the family goes back to Greek eugenēs, “well-born, noble”.','Jevgenija – vardo Jevgeņija rašyba su n vietoj ņ; šeima kyla iš graikų eugenēs („kilmingas“).','Jevgenija on nime Jevgeņija kirjapilt n-iga ņ asemel; nimepere aluseks on kreeka eugenēs ‘hästi sündinud, üllas’.')],
 ['Vikentijs is the Bulgarian, Russian and Ukrainian form of Vincentijs.',A('Vikentijs ir vārda Vincentijs slāvu forma.','Vikentijs — славянская форма имени Vincentijs.','Vikentijs is a Slavic form of Vincentijs.','Vikentijs – slaviška vardo Vincentijs forma.','Vikentijs on nime Vincentijs slaavi kuju.')],
 ['Jeļizaveta belongs to the Russian and Ukrainian branch of the Elizabete family.',A('Jeļizaveta pieder Elizabetes vārdu saimes slāvu zaram.','Jeļizaveta относится к славянской ветви семейства имени Elizabete.','Jeļizaveta belongs to the Slavic branch of the Elizabete family.','Jeļizaveta priklauso slaviškajai Elizabetės vardų šeimos šakai.','Jeļizaveta kuulub nime Elizabete pere slaavi harusse.')],
 ['Russian Zlata (Злата) is written Zlata in Latvian.',A('Zlata ir slāvu vārds; latviski to raksta tāpat.','Злата — славянское имя; по-латышски оно пишется Zlata.','Zlata is a Slavic name, written the same way in Latvian.','Zlata – slaviškas vardas; latviškai rašomas taip pat.','Zlata on slaavi nimi, mida läti keeles kirjutatakse samamoodi.')],
 ['Manefa still needs checking against Russian Manefa / Manethōn.',A('Vārda Manefa cilme vēl jāpārbauda.','Происхождение имени Manefa ещё нужно проверить.','The origin of Manefa still needs checking.','Vardo Manefa kilmę dar reikia patikrinti.','Nime Manefa päritolu tuleb veel kontrollida.')],
 ['Andrians is still being checked against Russian Андриан and Andriāns.',A('Andrians vēl tiek salīdzināts ar Andriāns.','Andrians ещё сопоставляют с Andriāns.','Andrians is still being checked against Andriāns.','Andrians dar lyginamas su Andriāns.','Andriansi võrreldakse veel kujuga Andriāns.')],
 ['Andrijans is still being checked against Russian Андриян and Adriāns.',A('Andrijans vēl tiek salīdzināts ar Adriāns.','Andrijans ещё сопоставляют с Adriāns.','Andrijans is still being checked against Adriāns.','Andrijans dar lyginamas su Adriāns.','Andrijansi võrreldakse veel nimega Adriāns.')],
 ['Ņika is still being checked against Russian Ника / Nika.',A('Ņika vēl tiek salīdzināta ar Nika.','Ņika ещё сопоставляют с Nika.','Ņika is still being checked against Nika.','Ņika dar lyginama su Nika.','Ņikat võrreldakse veel nimega Nika.')],
 ['Snežana is compared with Russian snezhinka, “snowflake”.',A('Snežanu salīdzina ar slāvu vārdu sniegpārslai.','Снежану сопоставляют со славянским словом «снежинка».','Snežana is compared with a Slavic word for “snowflake”.','Snežana lyginama su slavų žodžiu „snaigė“.','Snežanat võrreldakse slaavi sõnaga ‘lumehelves’.')],
 ['Akims is compared with Russian Akim, a form of Joachim, which is linked with the biblical names Jehoiachin or Jehoiakim.',A('Akims ir vārda Joahims forma; to saista ar Bībeles vārdiem Jojahins vai Jojakims.','Akims — форма имени Иоаким, связанного с библейскими именами Иехония или Иоаким.','Akims is a form of Joachim, which is linked with the biblical names Jehoiachin or Jehoiakim.','Akims – vardo Joachimas forma, siejama su Biblijos vardais Jehojachinas ar Jehojakimas.','Akims on nime Joachim kuju, mida seostatakse piiblinimedega Jojakin või Jojakim.')],
 ['A Russian tradition also explains it as “seagull”, but that remains only one interpretation.',A('Cita tradīcija to skaidro arī kā «kaija», taču tas ir tikai viens skaidrojums.','Другая традиция толкует его и как «чайка», но это лишь одно из толкований.','Another tradition also explains it as “seagull”, but that remains only one interpretation.','Kita tradicija jį aiškina ir kaip „žuvėdra“, bet tai tik vienas aiškinimas.','Teine traditsioon seletab seda ka kui ‘kajakas’, kuid see on vaid üks tõlgendus.')],
 ['Jurga is tied to the history of Jurgis, which goes back to Greek Geōrgios, from geōrgós, “farmer”, and reached Lithuanian through Old Russian Jurg’ and Jurgij.',A('Jurga saistīta ar vārda Jurgis vēsturi; tas iet atpakaļ uz grieķu Geōrgios, no geōrgós — «zemkopis».','Jurga связана с историей имени Jurgis, восходящего к греческому Geōrgios, от geōrgós — «земледелец».','Jurga is tied to the history of Jurgis, which goes back to Greek Geōrgios, from geōrgós, “farmer”.','Jurga susijusi su vardo Jurgis istorija; jis kyla iš graikų Geōrgios, nuo geōrgós („žemdirbys“).','Jurga on seotud nime Jurgis ajalooga; Jurgis ulatub kreeka nimeni Geōrgios sõnast geōrgós ‘põllumees’.')],
 ['The name reached Lithuanian through East Slavic languages even before the country’s conversion, and in eastern Aukštaitija the dialect form Untanas can still be heard.',A('Lietuviešu valodā vārds ienāca jau pirms zemes kristīšanas, un Austrumaukštaitijā vēl dzirdama izloksnes forma Untanas.','В литовский язык имя пришло ещё до крещения страны, и в восточной Аукштайтии до сих пор слышна диалектная форма Untanas.','The name reached Lithuanian even before the country’s conversion, and in eastern Aukštaitija the dialect form Untanas can still be heard.','Į lietuvių kalbą vardas atėjo dar prieš krikštą, o rytų Aukštaitijoje tebegirdima tarminė forma Untanas.','Leedu keelde jõudis nimi juba enne maa ristiusustamist ja Ida-Aukštaitijas kuuleb veel murdekuju Untanas.')],
 ['In Lithuanian Jekaterina is used for Russian empresses such as Catherine II, following Russian Ekaterina; the usual Lithuanian form of Katharina is Kotryna.',A('Lietuviešu valodā Jekaterina tiek lietota tādām ķeizarienēm kā Katrīna II; parastā lietuviešu Katrīnas forma ir Kotryna.','В литовском Jekaterina употребляют для императриц, таких как Екатерина II; обычная литовская форма имени Катерина — Kotryna.','In Lithuanian Jekaterina is used for empresses such as Catherine II; the usual Lithuanian form of Katharina is Kotryna.','Lietuvių kalboje Jekaterina vartojama tokioms imperatorėms kaip Jekaterina II; įprasta lietuviška Katharinos forma – Kotryna.','Leedu keeles kasutatakse nime Jekaterina selliste keisrinnade puhul nagu Katariina II; tavaline leedu Katharina kuju on Kotryna.')],
 ['Liia belongs to the group of Lea and Lia; its spelling was influenced by Russian Liya (Лия).',A('Liia pieder pie vārdu Lea un Lia grupas.','Liia относится к группе имён Lea и Lia.','Liia belongs to the group of Lea and Lia.','Liia priklauso vardų Lea ir Lia grupei.','Liia kuulub nimede Lea ja Lia rühma.')],
 ['Paavel is an Estonian form of Paul, modelled most closely on Russian Павел.',A('Paavel ir vārda Pāvils igauņu forma.','Paavel — эстонская форма имени Павел.','Paavel is an Estonian form of Paul.','Paavel – estiška vardo Paulius forma.','Paavel on nime Paul eesti kuju.')],
 ['Meljo is linked with Emil through Russian Yemelyan.',A('Meljo saistās ar Emil un Emiliāns.','Meljo связано с Emil и Emilian.','Meljo is linked with Emil and Emilian.','Meljo siejamas su Emil ir Emilian.','Meljo on seotud nimedega Emil ja Emilian.')],
 ['Varje belongs with Varju and, more tentatively, with Varja, a form of Barbara through Russian Varvara; it has also been explained as Estonian varje, “protection, refuge”.',A('Varje pieder pie Varju un, mazāk droši, pie Varja — Barbaras formas; to skaidro arī ar igauņu varje — «aizsardzība, patvērums».','Varje относится к Varju и, менее уверенно, к Varja — форме имени Варвара; его объясняют и эстонским varje — «защита, укрытие».','Varje belongs with Varju and, more tentatively, with Varja, a form of Barbara; it has also been explained as Estonian varje, “protection, refuge”.','Varje priklauso Varju ir, mažiau tikrai, Varja – Barboros formai; jis aiškinamas ir estų varje („apsauga, prieglobstis“).','Varje kuulub kokku Varjuga ja ebakindlamalt Varjaga, mis on Barbara kuju; seda on seletatud ka sõnaga varje ‘kaitse, varjupaik’.')],
 ['It belongs with Varje and, more tentatively, with Varja, a form of Barbara through Russian Varvara; Varje has also been explained as Estonian varje, “protection, refuge”.',A('Tas pieder pie Varje un, mazāk droši, pie Varja — Barbaras formas; Varje skaidro arī ar igauņu varje — «aizsardzība, patvērums».','Оно относится к Varje и, менее уверенно, к Varja — форме имени Варвара; Varje объясняют и эстонским varje — «защита, укрытие».','It belongs with Varje and, more tentatively, with Varja, a form of Barbara; Varje has also been explained as Estonian varje, “protection, refuge”.','Jis priklauso Varje ir, mažiau tikrai, Varja – Barboros formai; Varje aiškinamas ir estų varje („apsauga, prieglobstis“).','See kuulub kokku Varjega ja ebakindlamalt Varjaga, mis on Barbara kuju; Varjet on seletatud ka sõnaga varje ‘kaitse, varjupaik’.')],
 ['Russian Zhenya became the independent name Senni in Karelia and Estonia.',A('Mīlvārds Ženja (no Jevgeņija) Karēlijā un Igaunijā kļuva par patstāvīgu vārdu Senni.','Ласкательное Женя (от Евгения) в Карелии и Эстонии стало самостоятельным именем Senni.','The pet form Zhenya (from Yevgeniya) became the independent name Senni in Karelia and Estonia.','Maloninė forma Ženia (iš Jevgenija) Karelijoje ir Estijoje tapo savarankišku vardu Senni.','Hellitusvorm Ženja (nimest Jevgenija) muutus Karjalas ja Eestis iseseisvaks nimeks Senni.')],
 ['Pakerys documents exact Dargintė accent variants in 2011, but elsewhere notes that some related dar- names may continue darg-.',A('Ir zināmi tieši Dargintė uzsvara varianti, un dažu radniecīgu dar- vārdu pamatā var būt darg-.','Известны варианты ударения именно Dargintė, и некоторые родственные имена на dar- могут восходить к darg-.','Accent variants of exactly Dargintė are known, and some related dar- names may continue darg-.','Žinomi būtent Dargintė kirčiavimo variantai, o kai kurie giminingi dar- vardai gali būti kilę iš darg-.','Teada on just Dargintė rõhuvariandid ning mõned sugulased dar-nimed võivad jätkata tüve darg-.')],
 ['Sinkevičiūtė’s linguistic review corrects Vitautė to Vytautė; Pakerys also discusses the exact feminine form in 2011.',A('Rakstība Vitautė ir labota uz Vytautė.','Написание Vitautė исправлено на Vytautė.','The spelling Vitautė has been corrected to Vytautė.','Rašyba Vitautė pataisyta į Vytautė.','Kirjapilt Vitautė on parandatud kujule Vytautė.')],
 ['The source itself questions this origin, so it remains an unverified proposal.',A('Šī cilme pati par sevi ir apšaubāma, tādēļ tā saglabāta kā nepārbaudīts pieņēmums.','Это происхождение само по себе сомнительно, поэтому остаётся непроверенным предположением.','This origin is itself doubtful, so it remains an unverified proposal.','Ši kilmė pati savaime abejotina, todėl lieka nepatikrinta prielaida.','See päritolu on iseenesest kahtlane, seega jääb see kontrollimata oletuseks.')],
 ['The source places Igo under Hugo but marks a possible Ignāts connection with a question mark.',A('Igo parasti saista ar Hugo, bet iespējamā saikne ar Ignāts ir apšaubāma.','Igo обычно связывают с Hugo, а возможная связь с Ignāts сомнительна.','Igo is usually placed with Hugo, while a possible Ignāts connection is doubtful.','Igo paprastai siejamas su Hugo, o galimas ryšys su Ignāts abejotinas.','Igo seostatakse tavaliselt nimega Hugo, võimalik seos nimega Ignāts on aga kahtlane.')],
 ['For Vīgants the source gives Lithuanian vyti, ginti and ganyti alongside Old High German wigand, warrior, without selecting one origin.',A('Vīgants tiek saistīts gan ar lietuviešu vyti, ginti un ganyti, gan ar senaugšvācu wigand — «karotājs»; viena cilme nav izvēlēta.','Vīgants связывают и с литовскими vyti, ginti и ganyti, и с древневерхненемецким wigand — «воин»; одно происхождение не выбрано.','Vīgants is linked both with Lithuanian vyti, ginti and ganyti and with Old High German wigand, warrior, without one origin being chosen.','Vīgants siejamas ir su lietuvių vyti, ginti bei ganyti, ir su senosios aukštaičių vokiečių wigand („karys“); viena kilmė nepasirinkta.','Vīgantsi seostatakse nii leedu sõnadega vyti, ginti ja ganyti kui ka vanaülemsaksa sõnaga wigand ‘sõdalane’; üht päritolu pole valitud.')],
 ['Separately, the source documents use of the exact form in Liepāja in 1976; that date does not settle the origin.',A('Atsevišķi precīzās formas lietojums dokumentēts Liepājā 1976. gadā; šis datējums izcelsmes jautājumu neatrisina.','Отдельно употребление точной формы документировано в Лиепае в 1976 году; эта дата не решает вопрос о происхождении.','Separately, use of the exact form is documented in Liepāja in 1976; that date does not settle the origin.','Atskirai tikslios formos vartojimas dokumentuotas Liepojoje 1976 metais; ši data kilmės klausimo neišsprendžia.','Eraldi on täpse kuju kasutus dokumenteeritud Liepājas 1976. aastal; see kuupäev päritolu küsimust ei lahenda.')],
 ['Separately, the source documents use of the exact form in Talsi in 1977; that date does not settle the origin.',A('Atsevišķi precīzās formas lietojums dokumentēts Talsos 1977. gadā; šis datējums izcelsmes jautājumu neatrisina.','Отдельно употребление точной формы документировано в Талси в 1977 году; эта дата не решает вопрос о происхождении.','Separately, use of the exact form is documented in Talsi in 1977; that date does not settle the origin.','Atskirai tikslios formos vartojimas dokumentuotas Talsuose 1977 metais; ši data kilmės klausimo neišsprendžia.','Eraldi on täpse kuju kasutus dokumenteeritud Talsis 1977. aastal; see kuupäev päritolu küsimust ei lahenda.')],
 ['Separately, the source documents use of the exact form near Talsi in 1975; that date does not settle the origin.',A('Atsevišķi precīzās formas lietojums dokumentēts Talsu apkaimē 1975. gadā; šis datējums izcelsmes jautājumu neatrisina.','Отдельно употребление точной формы документировано под Талси в 1975 году; эта дата не решает вопрос о происхождении.','Separately, use of the exact form is documented near Talsi in 1975; that date does not settle the origin.','Atskirai tikslios formos vartojimas dokumentuotas prie Talsų 1975 metais; ši data kilmės klausimo neišsprendžia.','Eraldi on täpse kuju kasutus dokumenteeritud Talsi lähedal 1975. aastal; see kuupäev päritolu küsimust ei lahenda.')],
 ['The source itself questions these proposals.',A('Šīs versijas ir apšaubāmas.','Эти версии сомнительны.','These proposals are doubtful.','Šios versijos abejotinos.','Need oletused on kahtlased.')],
 ['The catalogue explicitly distinguishes this spelling from the source’s form.',null],
 ['The source form belongs to the Daniel family, from Hebrew dānīēl, “God is my judge”.',A('Sākotnējā forma pieder Daniel saimei, no ebreju dānīēl — «Dievs ir mans tiesnesis».','Исходная форма относится к семейству имени Даниил, от еврейского dānīēl — «Бог — мой судья».','The original form belongs to the Daniel family, from Hebrew dānīēl, “God is my judge”.','Pradinė forma priklauso Danieliaus šeimai, iš hebrajų dānīēl („Dievas – mano teisėjas“).','Algvorm kuulub Danieli perre, heebrea sõnast dānīēl ‘Jumal on mu kohtumõistja’.')],
 ['The source form belongs to the David family, explained through Hebrew Dāvīd, “beloved”.',A('Sākotnējā forma pieder David saimei, ko skaidro ar ebreju Dāvīd — «mīlētais».','Исходная форма относится к семейству имени Давид, от еврейского Dāvīd — «любимый».','The original form belongs to the David family, explained through Hebrew Dāvīd, “beloved”.','Pradinė forma priklauso Dovydo šeimai, aiškinamai hebrajų Dāvīd („mylimasis“).','Algvorm kuulub Taaveti perre, mida seletatakse heebrea sõnaga Dāvīd ‘armastatu’.')],
 ['This remains an unverified comparison: the source documents Juozapatas, not a correspondence between the two forms.',A('Šī ir pagaidām nepārbaudīta formu salīdzināšana: dokumentēta ir Juozapatas, bet ne abu rakstību savstarpēja atbilsme.','Пока это непроверенное сравнение форм: документировано Juozapatas, но не соответствие двух написаний.','This remains an unverified comparison: Juozapatas is documented, but not a correspondence between the two forms.','Kol kas tai nepatikrintas formų palyginimas: dokumentuotas Juozapatas, bet ne abiejų rašybų atitiktis.','See on seni kontrollimata vormivõrdlus: dokumenteeritud on Juozapatas, mitte kahe kirjapildi vastavus.')],
 ['It offers Old Norse sigr, victory, with rīdan, to ride, or a comparison with Sigridh and beauty.',A('Piedāvāti skaidrojumi ar sennorvēģu sigr — «uzvara» — un rīdan — «jāt» — vai salīdzinājums ar Sigridh un skaistuma nozīmi.','Предлагают объяснения через древнескандинавское sigr — «победа» — и rīdan — «ехать верхом» — или сравнение с Sigridh и значением «красота».','Proposals include Old Norse sigr, victory, with rīdan, to ride, or a comparison with Sigridh and beauty.','Siūlomi aiškinimai iš senovės skandinavų sigr („pergalė“) ir rīdan („joti“) arba palyginimas su Sigridh ir grožio reikšme.','Pakutud on vanapõhja sõnu sigr ‘võit’ ja rīdan ‘ratsutama’ või võrdlust nimega Sigridh ja ilu tähendusega.')],
 ['The catalogue presents the explanation cautiously, so Hugo’s Germanic hugu, mind or spirit, supports a comparison rather than a verified Higo etymology.',A('Hugo ģermāņu hugu — «prāts, gars» — tādēļ ir tikai salīdzinājuma pamats, nevis pārbaudīta Higo cilme.','Германское hugu имени Hugo — «ум, дух» — поэтому лишь основа для сравнения, а не проверенная этимология Higo.','Hugo’s Germanic hugu, mind or spirit, therefore supports only a comparison, not a verified Higo etymology.','Hugo germaniškas hugu („protas, dvasia“) todėl tėra palyginimo pagrindas, o ne patikrinta Higo kilmė.','Hugo germaani hugu ‘mõistus, vaim’ annab seega vaid võrdlusaluse, mitte kontrollitud Higo päritolu.')],
 ['However, the catalogue leaves this exact form’s origin unresolved; a reference to Brīva does not yet prove derivation.',A('Tomēr tieši šīs formas cilme nav atrisināta; norāde uz Brīva vēl nepierāda atvasinājumu.','Однако происхождение именно этой формы не решено; отсылка к Brīva ещё не доказывает образование.','However, this exact form’s origin is unresolved; a reference to Brīva does not yet prove derivation.','Tačiau būtent šios formos kilmė neišspręsta; nuoroda į Brīva dar neįrodo darybos.','Selle täpse kuju päritolu on siiski lahendamata; viide nimele Brīva ei tõesta veel tuletust.')],
 ['A catalogue cross-reference and similar search results do not establish the transition.',null],
 ['The Latvian catalogue leaves the form unresolved and points towards a Nana comparison.',A('Latviešu formas cilme nav atrisināta; iespējams salīdzinājums ar Nana.','Происхождение латышской формы не решено; возможно сравнение с Nana.','The Latvian form remains unresolved; a comparison with Nana is possible.','Latviškos formos kilmė neišspręsta; galimas palyginimas su Nana.','Läti kuju päritolu on lahendamata; võimalik on võrdlus nimega Nana.')],
 ['The catalogue explicitly notes the difference and the Language Agency search yielded no exact pair.',null],
 ['This remains an unverified working proposal: the reference does not provide an unambiguous correspondence for this exact spelling.',A('Tā paliek nepārbaudīta darba versija: tieši šai rakstībai nepārprotama atbilsme nav atrasta.','Это остаётся непроверенной рабочей версией: однозначного соответствия именно для этого написания не найдено.','This remains an unverified working proposal: no unambiguous correspondence has been found for this exact spelling.','Tai lieka nepatikrinta darbo versija: būtent šiai rašybai vienareikšmės atitikties nerasta.','See jääb kontrollimata tööversiooniks: just selle kirjapildi kohta pole ühemõttelist vastet leitud.')],
 ['The Nordic Names reference links it with the Estonian word ülev, “lofty, noble-minded”.',A('To saista ar igauņu vārdu ülev — «cildens, cēls».','Его связывают с эстонским словом ülev — «возвышенный, благородный».','It is linked with the Estonian word ülev, “lofty, noble-minded”.','Jis siejamas su estų žodžiu ülev („kilnus, prakilnus“).','Seda seostatakse sõnaga ülev.')],
 ...['Aleksandris|Aleksandrs','Alesandrs|Aleksandrs','Zandars|Zanders'].map(x=>{const [n,b]=x.split('|');return [`${n} can be compared by spelling with ${b}, but the checked catalogue’s explanation belongs to ${b}, not this exact form.`,A(`${n} pēc rakstības var salīdzināt ar ${b}, taču ${b} skaidrojums neattiecas tieši uz šo formu.`,`${n} по написанию можно сравнить с ${b}, но объяснение ${b} не относится именно к этой форме.`,`${n} can be compared by spelling with ${b}, but the explanation of ${b} does not apply to this exact form.`,`${n} pagal rašybą galima palyginti su ${b}, tačiau ${b} aiškinimas netaikomas būtent šiai formai.`,`${n} võib kirjapildi järgi võrrelda nimega ${b}, kuid ${b} seletus ei kehti just selle kuju kohta.`)];}),
 ...['Aleksandrs','Zanders'].map(b=>[`{name} can be compared by spelling with ${b}, but the checked catalogue’s explanation belongs to ${b}, not this exact form.`,A(`{name} pēc rakstības var salīdzināt ar ${b}, taču ${b} skaidrojums neattiecas tieši uz šo formu.`,`{name} по написанию можно сравнить с ${b}, но объяснение ${b} не относится именно к этой форме.`,`{name} can be compared by spelling with ${b}, but the explanation of ${b} does not apply to this exact form.`,`{name} pagal rašybą galima palyginti su ${b}, tačiau ${b} aiškinimas netaikomas būtent šiai formai.`,`{name} võib kirjapildi järgi võrrelda nimega ${b}, kuid ${b} seletus ei kehti just selle kuju kohta.`)]),
]);
