function fixLang(text){let changed=false;const out={...text};for(const [l,list] of Object.entries(FIX)){if(!text[l])continue;out[l]=text[l].map(p=>{for(const [a,b] of list)if(p.includes(a)){p=p.split(a).join(b);changed=true;}return p;});}return changed?out:text;}
export function wordingFor(sentence){return W.get(sentence);}
export function hasWording(sentence){return W.has(sentence);}
// Apply the map to a five-language text object. English decides; other languages change the sentence at the
// same position when sentence-aligned, or the whole paragraph when the English paragraph is one sentence.
export function applyWording(text,split){
 const L=['lv','ru','en','lt','et'],en=text.en||[];let touched=false;
 const plan=en.map(p=>split(p).map(s=>W.has(s)?{v:W.get(s)}:null));
 if(!plan.some(p=>p.some(Boolean)))return fixLang(text);
 const out={};
 for(const [li,l] of L.entries()){
  out[l]=(text[l]||[]).map((p,i)=>{const pl=plan[i];if(!pl||!pl.some(Boolean))return p;
   const s=split(p);
   if(s.length===pl.length)return s.map((x,k)=>pl[k]?(pl[k].v?pl[k].v[li]:''):x).filter(Boolean).join(' ');
   if(pl.length===1)return pl[0].v?pl[0].v[li]:'';
   return p;}).filter(Boolean);
  if(!out[l].length)out[l]=text[l]||[];
 }
 return fixLang({...text,...out});
}
